/* 第二十五章 · 绵竹血战 — 1:1 演出流，逆向自 R_25.eex */
(function(){
 if(!window.JW_CHAPTERS) window.JW_CHAPTERS=[];
 window.JW_CHAPTERS.push({"id":"ch25","num":25,"title":"第二十五章 · 绵竹血战","desc":"第二十五章 · 绵竹血战（原版剧本 R_25.eex 完整演出流）","intro":{"title":"第二十五章 · 绵竹血战","script":[{"op":"clear_flags","args":[]},{"op":"play_sound","args":[40]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[645,34,54,1,0]},{"op":"actor_appear","args":[105,48,43,2,0]},{"op":"actor_appear","args":[121,48,69,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["邓艾的考量"]},{"op":"place_name","args":["上邽 魏军营帐"]},{"op":"actor_face","args":[105,6,3]},{"op":"dialog","args":["&邓忠\n爹，要追击吗？\n&邓艾1\n忠儿，还在埋怨爹？\n&邓忠\n没这回事。\n&邓艾1\n在战场上和敌人以力相搏的时代已经过去\n，现在是靠谋略和胆量致胜的时代。\n&邓忠\n过去您也是靠著一身武艺得到这个位子\n，为什么现在会变成这样？\n&邓艾1\n过去吕布天下无敌，结果如何？关羽威震\n华夏，结果又如何？\n&邓艾1\n当看见已故的太傅成功那刻，我终于\n明白了这些道理。\n&邓忠\n………\n&邓艾1\n以后随著年纪渐长，你会明白的。\n&邓艾1\n现在号令全军，不要再追击了。"]},{"op":"actor_face","args":[121,0,3]},{"op":"dialog","args":["&郑伦\n明明我军打了胜仗，为什么不追了？\n&邓艾1\n姜维军队还是有相当的战斗能力，万一被\n他引进熟悉的地形，我们不见得能打赢。\n&邓艾1\n到时万一被打败，眼前的战功将化为乌有\n，不如见好就收。\n&邓艾1\n（更何况我会成为陇西都督，还是因为\n姜维在这边搞得天翻地覆。留著姜维，\n我的地位将不可动摇。）\n&邓艾1\n（只是大将军真的只是因为我可以对付\n姜维才要我来这边？还是准备用我来逼退\n陈泰？还是作为切割都督区的试验？）\n&邓艾1\n（真可怕啊…一个安排背后有那么多考量\n，这个司马昭一点也不比他父亲逊色。）"]},{"op":"if","cond":"test_flags","args":[[910],[]],"end":16},{"op":"dialog","args":["&邓艾1\n（倒是这次本来应该大胜的战争，被那\n张嶷搞到惨胜，这家伙快变成挥之不去\n的梦魇。）\n&邓艾1\n（从二十多年前，我就在规划偷渡阴平的\n作战计画，但万一被张嶷埋伏呢？）"]},{"op":"endif","args":[]},{"op":"delay","args":[5]},{"op":"dialog","args":["邓艾因段谷上邽一战的功劳，被擢升为\n镇西将军，都督陇右诸军事，正式成为\n曹魏的地方大员。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[31]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[0,35,54,1,0]},{"op":"actor_appear","args":[4,51,45,2,0]},{"op":"actor_appear","args":[3,56,45,2,0]},{"op":"actor_appear","args":[8,61,45,2,0]},{"op":"actor_appear","args":[10,66,45,2,0]},{"op":"actor_appear","args":[217,71,45,2,0]},{"op":"actor_appear","args":[9,46,66,0,0]},{"op":"actor_appear","args":[15,51,66,0,0]},{"op":"actor_appear","args":[2,56,66,0,0]},{"op":"actor_appear","args":[5,61,66,0,0]},{"op":"actor_appear","args":[16,66,66,0,0]},{"op":"if","cond":"test_flags","args":[[],[907]],"end":16},{"op":"actor_appear","args":[22,71,66,0,0]},{"op":"endif","args":[]},{"op":"fade_out","args":[]},{"op":"title_text","args":["姜维的痛悔"]},{"op":"place_name","args":["姜维军营帐"]},{"op":"dialog","args":["&姜维\n………"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[5,6,3]},{"op":"dialog","args":["&宁随\n关统将军已经确定战死了，夏侯霸将军\n也在乱军中下落不明…\n&姜维\n我知道！所以我要在这边继续等下去！\n&宁随\n夏侯将军生还的机会很低，我们不该浪费\n宝贵的时间等下去。\n&宁随\n应该趁著邓艾还没有追击想法的时候赶快\n撤退，不然要是我们两军再交战，绝对没\n有战胜的可能性。\n&姜维\n这些我都知道…"]},{"op":"actor_face","args":[10,6,3]},{"op":"dialog","args":["&向充\n大将军，该退的时候就要退，我们真的\n没有本钱再继续打下去了。\n&姜维\n因为我的错误判断，一口气让两位大将\n葬身在战场上…\n&张翼\n………\n&柳隐\n（张翼今天怎么这么老实，没有说一句话\n呢？）\n&来忠\n（这个罪恶感，压迫得我快喘不过气来，\n我该怎么办？）"]},{"op":"if","cond":"test_flags","args":[[910],[]],"end":29},{"op":"actor_face","args":[22,6,3]},{"op":"dialog","args":["&张嶷\n伯约，这场仗至少还给了敌人相当程度的\n反击，已经是足够了。\n&张嶷\n我想就算是邓艾，短时间内也不至于会\n入侵大汉。所以，请不要再责备自己。"]},{"op":"endif","args":[]},{"op":"actor_face","args":[16,6,3]},{"op":"dialog","args":["&关索\n伯约，赶快撤退吧，我可不希望关统的\n牺牲就这样白费。\n&关索\n关于车骑将军的事情，我会负责和星彩\n说，请不要担心。"]},{"op":"actor_face","args":[2,0,3]},{"op":"dialog","args":["&杨兰\n好了！你还继续在这边痛悔也是没用，\n重要的是要如何收拾残局！\n&杨兰\n（我可以预见，站在亲魏立场的姚柯回，\n势力将会日渐壮大，该怎么办呢？）\n&王嗣\n（其实这场仗最大的损失，恐怕是陇西\n这边，日后难以再获得在地人或是羌人\n的协助，这点杨姑娘应该也很清楚。）\n&姜维\n（一时的失败不算什么，只要还有一口气\n在，总有一天会再回到这里。）"]},{"op":"actor_action","args":[0,17]},{"op":"dialog","args":["&姜维\n嗯…全军全速撤回汉中，所有辎重装备，\n若是不能带走就原地销毁，全军轻装前进\n，不要拖延到撤退速度。\n&宁随\n（好了，接下来就是我的工作…）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[31]},{"op":"change_scene","args":[2,65535,65535,50,65535]},{"op":"actor_appear","args":[49,52,77,0,0]},{"op":"actor_appear","args":[50,59,73,0,0]},{"op":"actor_appear","args":[257,39,61,1,0]},{"op":"actor_appear","args":[42,65,61,3,0]},{"op":"actor_appear","args":[40,65,56,3,0]},{"op":"actor_appear","args":[55,39,56,1,0]},{"op":"actor_appear","args":[51,39,51,1,0]},{"op":"actor_appear","args":[47,39,46,1,0]},{"op":"actor_appear","args":[652,65,51,3,0]},{"op":"actor_appear","args":[155,65,46,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["尹赏之怒"]},{"op":"place_name","args":["成都 皇宫"]},{"op":"actor_face","args":[55,6,2]},{"op":"dialog","args":["&谯周\n陛下，纵然不想面对也请您面对，这已经\n是关系到大汉存亡的问题了。\n&谯周\n丧师无数，还让虎贲中郎将关统和车骑将\n军夏侯霸战死沙场，把从丞相以来获得的\n战果毁于一旦，这都是姜维的错。\n&刘禅\n皇后现在情况怎么样了？"]},{"op":"actor_face","args":[50,0,3]},{"op":"dialog","args":["&黄皓\n现在情绪已经平稳很多，没有当初听到\n车骑将军死讯那样激动了。\n&谯周\n圣上！"]},{"op":"actor_face","args":[55,0,1]},{"op":"actor_face","args":[47,6,2]},{"op":"dialog","args":["&董厥\n臣也要请陛下三思，一任用姜维这样的\n外人担任大将军，就出现这样的灾难，\n再让他当下去，大汉社稷恐怕危险了。"]},{"op":"if","cond":"test_flags","args":[[910],[]],"end":25},{"op":"dialog","args":["&郤正\n有件事情我很不明白，想要请教二位…\n&郤正\n首先是允南（谯周），为什么你只字不提\n伯约他在逆境中击退邓艾的事情？\n&郤正\n纵然我军损失惨重，也算是惨胜，还是\n足够让曹贼断绝进攻的念头。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[910]],"end":28},{"op":"dialog","args":["&郤正\n有件事情我很不明白，想要请教二位…\n&郤正\n首先是允南（谯周），这次纵然是惨败，\n但是姜维难道是唯一要负责任的人？\n&郤正\n请问当时带著大军在汉中附近转圈圈的\n胡济该如何？"]},{"op":"endif","args":[]},{"op":"dialog","args":["&郤正\n接著是龚袭（董厥），为什么同样是出身\n自丞相府的你，会特别对伯约有意见？请\n问他所做的，和丞相做的有什么不同？"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&樊建\n（这个郤正平常不太开口，一开口就无比\n犀利。眼前只有一个人可以压倒他，但那\n个人靠著是他的家世，不是口才。）\n&樊建\n（这个时候我也不知道该怎么办，我对\n姜维并没有特殊的感情，但之前他涉嫌\n暗算文伟的事还是让我耿耿于怀。）"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[40,2,0]},{"op":"dialog","args":["&诸葛瞻\n郤正！父亲的作为可以让你随便提出来和\n姜维类比吗？\n&诸葛瞻\n他认可的接班人是蒋公琰和费文伟，绝对\n不是姜维。\n&诸葛瞻\n姜维偷窃我爹辛苦多年的成果，把我爹为\n大汉苦心存下来的资本投入没有意义的战\n争中，到最后只换得他的大将军之位。\n&诸葛瞻\n这些事情尚书仆射（董厥）他比谁都清楚\n，正因为他是出身自爹丞相府的官员，\n他更想维护爹一手撑起来的大汉！\n&郤正\n………\n&郤正\n（无法反驳啊，在丞相这块神主牌面前，\n谁都不能多说一句话，哪怕是圣上也不行\n多说。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&刘禅\n那么，侍中你要我怎么做？"]},{"op":"actor_face","args":[40,6,2]},{"op":"dialog","args":["&诸葛瞻\n罢免姜维，改派值得信任的人接替他担任\n大将军。\n&刘禅\n嗯…这件事情，朕还是想要问一下尚书令\n的意见。\n&陈祗\n这…"]},{"op":"actor_face","args":[40,0,3]},{"op":"delay","args":[5]},{"op":"actor_move","args":[0,155,0,60,46,3]},{"op":"delay","args":[0]},{"op":"actor_move","args":[0,155,0,60,56,1]},{"op":"actor_face","args":[155,0,1]},{"op":"actor_action","args":[155,0]},{"op":"dialog","args":["&尹赏\n诸葛瞻！你到底知道伯约多少？你什么\n都不知道就在胡说一气！\n&尹赏\n我是在天水时期就认识伯约，他虽然有些\n任性，而且胆大妄为，但是他对人诚恳，\n行事光明磊落，绝对是时人的典范。\n&尹赏\n许多人污蔑他杀害费祎，我认为这是\n最恶劣的中伤。\n&尹赏\n伯约当时面对恶意陷害他的马遵，他都只\n有默默承受，何况只是因为政治意见不同\n而和费祎有争执而已。\n&尹赏\n至于说伯约偷窃丞相的成果，那更是可笑\n无比。\n&尹赏\n请问伯约如今的地位，有哪一些不是靠\n自己打下来的？洮西大捷，纵然是丞相\n五次北伐也都没有过这样的胜利。\n&樊建\n执金吾，你似乎说得有些过火了…"]},{"op":"actor_face","args":[155,0,3]},{"op":"dialog","args":["&尹赏\n过火？刚才几位批评伯约的话就不过火，\n只看见伯约的失败，却忽视伯约对大汉的\n贡献，以及他为大汉的牺牲。\n&尹赏\n他忍受著和亲人分离的孤独，坚持要回报\n丞相和陛下对他的恩情。\n&尹赏\n而如今，丞相的爱子不明白这一切，居然\n污蔑伯约的赤诚之心，让人听得怎么不怒\n火中烧。"]},{"op":"actor_face","args":[155,0,1]},{"op":"dialog","args":["&尹赏\n你只是一个无用的公子哥，靠丞相的名声\n在混饭吃，什么都没做，世人就会把功劳\n归给你！\n&诸葛瞻\n你……\n&尹赏\n既然你这么行，为什么不亲自领军去对抗\n邓艾？你行吗？"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&陈祗\n执金吾，再怎么体谅你的心情，这样说话\n都似乎太过分了。\n&陈祗\n你口出恶言，侮辱到丞相之子甚至是丞相\n，这已经是很严重的罪行。"]},{"op":"actor_face","args":[155,0,3]},{"op":"dialog","args":["&尹赏\n哈哈哈，我尹赏窝囊了一辈子，今天总算\n想通了，不想再受这样的鸟气。\n&尹赏\n我为什么要怕你或是诸葛瞻这种鸟官？\n&尹赏\n只会用嘴巴获得高位的人，和伯约根本就\n不能比。让你们这些废物当政，真是大汉\n的不幸！\n&尹赏\n（对不起，我只能陪你到这里了…伯约，\n到那边，我会和小妹一起庇佑你的。）"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[47,0,1]},{"op":"dialog","args":["&董厥\n这个尹赏简直是造反了！来人！来人！\n&郤正\n等一下，执金吾情况似乎不对！\n&尹赏\n………\n&诸葛瞻\n他死了？\n&谯周\n慷慨激昂，直立而逝，纵然立场不相同，\n但是精神让人感佩不已。\n&刘禅\n……即刻安葬他…\n&陈祗\n（尹赏啊，说得很完美，在场所有人都被\n你压倒了。）\n&陈祗\n（如果不是你，恐怕我也得跳下去对姜维\n发动攻击。只是，为什么你要为他做到\n这种地步？只为了虚幻的友情？）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[13]},{"op":"change_scene","args":[2,65535,65535,40,65535]},{"op":"actor_appear","args":[8,56,60,2,0]},{"op":"actor_appear","args":[668,56,66,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["来敏的悔恨"]},{"op":"place_name","args":["成都 来府"]},{"op":"dialog","args":["&来敏\n忠儿，你回来了…咳咳咳咳…\n&来忠\n爹，您憔悴了许多。\n&来敏\n老夫接到前线的战报时，差点以为你也\n遇难，那段期间可真是折腾死老夫了。\n&来忠\n爹，我们犯下的，可是滔天大罪呀。\n&来忠\n长久以来，我们认为自己是边缘人，所以\n处在危险的状态下，必须用尽心力来自保\n，否则就有灭亡的危机。\n&来忠\n但是，事实真的如此？刘敏将军暗示我的\n话，我到了最近才开始明白，并非所有人\n都对我们有敌意。\n&来忠\n大将军对我也推心置腹，这次的事情很明\n显是我们造成的，但他却没有过问我一句\n，还帮我挡住责难。\n&来忠\n爹您想想，过去您做的这一切，到底是谁\n得利？不断地挑拨，制造纷争，到最后是\n谁爬到高位？\n&来敏\n陈祗…老夫真是太低估他了，以为他只是\n个后生晚辈，哪知道他一瞬间就爬到这么\n高的位子。\n&来敏\n他都躲在后面，让老夫去和姜维对立，\n自己一方面在姜维面前装作是姜维的\n协力者。\n&来敏\n他面面俱到，整个朝中根本就没有人是他\n的敌人。更重要的是，连圣上都信任他。\n&来忠\n既然您已经知道这点，就此罢手好吗？\n我也打算向大将军请罪，任他处置，只\n希望他能阻止常败军的人向您报复。\n&来敏\n你说这什么话，老夫是行将就木的老人，\n哪怕什么报复！反而是你还年轻，怎么\n可以就这样葬送自己。\n&来忠\n我造的孽实在太多了，段谷之战中每个\n丧命的弟兄，实际上都是我杀的…\n&来敏\n不，其实是老夫造的孽，你不需要帮老夫\n去背负。"]},{"op":"actor_action","args":[8,6]},{"op":"dialog","args":["&来忠\n爹，就让我去面对吧，否则您要孩儿在\n接下来的人生都抬不起头来？\n&来敏\n这…"]},{"op":"delay","args":[10]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[13]},{"op":"change_scene","args":[2,65535,65535,41,65535]},{"op":"actor_appear","args":[16,52,54,2,0]},{"op":"actor_appear","args":[20,60,54,2,0]},{"op":"actor_appear","args":[213,56,60,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["战争的代价"]},{"op":"place_name","args":["成都车骑将军府"]},{"op":"dialog","args":["&关索\n我就知道你会在这里…\n&张皇后\n如果不透过收拾夏侯将军的遗物来整理\n心情的话，现在的我，恐怕会开始怨恨\n别人吧。\n&关索\n这件事情不是任何人的错，只要是战争\n就会带来这样的结果。\n&张皇后\n我知道…不过当年我爹也没听进去这样\n的话，不是吗？\n&关索\n我们关家最年轻一代的希望，在这场战争\n瞬息消失，其实我也不知道要怎么向去世\n的二哥交代。\n&张皇后\n那么你就不怨恨姜维？\n&关索\n不，事前看见关统那样浮躁的表现，\n却仍然没有阻止，责任都在我。\n&张皇后\n你可真会把责任往自己身上揽。"]},{"op":"actor_action","args":[20,2]},{"op":"dialog","args":["&花鬘\n够了！不要再对关索冷嘲热讽的啦！\n&张皇后\n记得你是…孟获的女儿？"]},{"op":"delay","args":[10]},{"op":"play_sound","args":[41]},{"op":"dialog","args":["&花鬘\n没错！我本来以为张飞的女儿有多了不起\n，哪知道只是个会耍脾气，一身公主病的\n笨女人而已的啦。\n&张皇后\n………\n&花鬘\n说不出话来？你想说什么就该大声说，\n装什么端庄？我呸！还皇后呢！"]},{"op":"actor_face","args":[16,0,1]},{"op":"dialog","args":["&关索\n花鬘！不要…\n&花鬘\n怕我骂哭你的星彩？\n&关索\n不是这样的…"]},{"op":"dialog","args":["&张皇后\n够了！老娘我已经够不爽了，你他妈还在\n那说什么鬼？\n&张皇后\n你是老鼠眼、鹰勾鼻、八字眉、招风耳、\n大翻嘴、黄板牙、鸡脖子、烂脖子、长短\n手、大小手、鸡胸、狗肚、饭桶腰。\n&张皇后\n你说你这个样子还是个人吗？我要是你呀\n，早就上吊自尽啦！\n&花鬘\n你…你敢骂我？小心不得好死！\n&张皇后\n我死了也要拉你当垫背的！\n&花鬘\n小心生儿子没屁眼！\n&张皇后\n没屁眼的儿子是你生的！\n&花鬘\n我看你能凶多久！\n&张皇后\n凶到你嗝屁为止！\n&张皇后\n你不化妆比化妆美，做鬼比做人好。\n我做人气得你发昏，做鬼吓跑你的魂。"]},{"op":"actor_action","args":[20,0]},{"op":"dialog","args":["&花鬘\n呜哇！\n（这女人吵架功力，真是不同凡响！）\n&关索\n我就说不要刺激她，她老爹张飞过去可是\n在瓦口关把张郃骂到吐血的。\n&张皇后\n呼…清爽多了，似乎我得感谢你和旁边\n那个笨女人。\n&花鬘\n呜呜呜…"]},{"op":"actor_face","args":[16,0,2]},{"op":"dialog","args":["&关索\n只希望你不要就此怨恨姜维才好，否则\n夏侯将军恐怕也无法安息的。\n&张皇后\n我知道，说不定对他来说，也希望战死\n沙场，而非就这样客死异乡吧。\n&张皇后\n（我总感觉，夏侯将军还活著，他不是个\n这么容易死的人。）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[17]},{"op":"change_scene","args":[2,65535,65535,0,65535]},{"op":"actor_appear","args":[7,47,32,2,1]},{"op":"actor_appear","args":[73,53,43,0,0]},{"op":"actor_appear","args":[727,46,43,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["奇迹的生还"]},{"op":"place_name","args":["谧友堂"]},{"op":"dialog","args":["&夏侯和\n二哥，果然是您！\n&夏侯霸\n这里是哪里？\n&夏侯和\n这里是神医皇甫谧的诊所，您中了好几箭\n，幸亏您得到他的医治，否则您早就已经\n不行了。"]},{"op":"delay","args":[10]},{"op":"dialog","args":["&皇甫谧\n别太看得起我，比起闻名天下的华陀，\n我可是差了一大截。\n&皇甫谧\n你能得救是因为这副铠甲，不然这箭\n再深几吋我也束手无策了。\n&夏侯霸\n果然这是父亲在天之灵的保佑。\n&皇甫谧\n好了，既然夏侯将军脱离险境，就让你们\n兄弟好好相处吧。\n&夏侯霸\n我该怎么感谢你？至少诊疗费该收一点\n吧。\n&皇甫谧\n不用谢我，医生治疗人是天职。\n&皇甫谧\n更何况我们“谧友堂”从来不收诊疗费\n的。"]},{"op":"actor_face","args":[73,6,3]},{"op":"dialog","args":["&夏侯和\n大夫，还是感谢您的救助！\n&夏侯霸\n救命之恩，没齿难忘。"]},{"op":"actor_action","args":[727,6]},{"op":"dialog","args":["&皇甫谧\n请夏侯将军记住一件事，在这里活著就\n表示上天有另外的安排。\n&皇甫谧\n找到自己的目标，完成自己的天命是您\n崭新人生接下来该做的事情。"]},{"op":"actor_move","args":[0,727,0,46,95,2]},{"op":"actor_select","args":[0,727,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[73,0,0]},{"op":"dialog","args":["&夏侯霸\n七弟，这几年你过得还好吗？其他两个\n弟弟怎么样了？\n&夏侯和\n六哥（夏侯惠）从辽东回来不久就去世\n，四哥（夏侯威）也在不久前病逝了，\n整个家就只剩下我一个人。\n&夏侯霸\n司马家没有迫害你吧？你现在还好？\n&夏侯和\n靠著侄女的关系，我和泰山羊家搭上线，\n司马家也就没有为难我。\n&夏侯霸\n原来如此，看来我的女婿羊叔子还有些\n办法。\n&夏侯和\n只是…因为有太初的那件事情发生，我\n被迫要对司马家卑躬屈膝，现在是司马昭\n大将军府的属官。\n&夏侯霸\n七弟，过去我怎么对你说的？\n&夏侯和\n二哥，我真的身不由己！\n&夏侯霸\n那么…你是来捉拿我的？\n&夏侯和\n怎么可能！我本来就在这附近要代表\n司马昭慰劳邓艾。\n&夏侯和\n我一听说您阵亡的消息就急忙赶到这附近\n要安葬您，没想到居然给我遇上了这样的\n奇迹。\n&夏侯和\n二哥，虽然我很没用，但是绝对不会出卖\n自己的亲人，请您一定要相信我！\n&夏侯和\n我拚著这条命，也要保护您的安全。\n&夏侯霸\n对不起，我错怪你了。\n&夏侯霸\n其实我根本没有理由说你，我自己不也是\n很自私地投奔蜀地，把你们害得这么惨。\n&夏侯和\n这样的选择是最好的，若是您还留在这边\n，恐怕就像太初那样被杀了。\n&夏侯霸\n我在那边虽然有些寂寞，但却有亲人相伴\n，想想我比你们幸福太多。\n&夏侯和\n亲人？\n&夏侯霸\n张飞的女儿，她是当年被掳去的那个从妹\n生下的孩子。\n&夏侯和\n哦？！这世界还真是小！\n&夏侯和\n二哥，请您要好好静养，等待时机。\n&夏侯霸\n嗯…我知道了。\n&夏侯和\n似乎蜀人把二哥您也变圆滑了，这样的\n转变并不是什么坏事。"]},{"op":"delay","args":[10]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[5]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[5,48,58,0,0]},{"op":"actor_appear","args":[10,48,53,2,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["最大的战争"]},{"op":"place_name","args":["姜维军军营"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&宁随\n这边的事情就交给你了，我现在就要启程\n到成都那边去。\n&向充\n老师，这次真的是辛苦您了，可惜常败军\n的人都不知道老师您真正的贡献。\n&宁随\n我本来就在战场上发挥不了太大的作用，\n更何况像我这种本来早就该死的人，哪里\n还需要让人家知道呢？\n&向充\n老师您这次的策略实在是很冒险，到底有\n几成把握可以说服对方呢？\n&宁随\n百分之百的把握。\n&宁随\n现在整个情势完全转变，本来是敌人的要\n拉拢，本来是我方的变成敌人，这点对方\n也知道。\n&向充\n我也没有想到，一向成为我们后盾的人们\n居然倒戈。而益州人早在之前就不支持\n我们。\n&宁随\n从公琰去世，许多老将凋零之后，我们的\n后盾就变得越来越弱。\n&宁随\n幸好来家父子已经被我们拉拢到，我要更\n进一步去拉拢这些刘璋旧部的非益州人来\n保护常败军。\n&向充\n郤正本来就对我们很友善，剩下果然就是\n那个人了…\n&向充\n只是，我还是很想问老师这个问题，明明\n如同廖立说的，让大将军掌控朝政，消除\n一切杂音就好了，为何老师不那样做？"]},{"op":"actor_action","args":[5,2]},{"op":"dialog","args":["&宁随\n你认为我会愿意去制造一个董卓或曹操？\n&向充\n老师！大将军不可能变成这两个恶棍的！\n&宁随\n这两个人也不是生下来就是恶棍，希望\n你能够明白这点。\n&向充\n可是丞相他也…\n&宁随\n住口！没有人可以和丞相相比，没有人\n可以…"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[46]},{"op":"change_scene","args":[2,65535,65535,23,65535]},{"op":"actor_appear","args":[5,38,53,1,0]},{"op":"actor_appear","args":[51,42,53,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["再次交易"]},{"op":"place_name","args":["成都郊外"]},{"op":"dialog","args":["&陈祗\n这次找我做什么？本来我应该下定决心要\n和你们切断关系的。\n&宁随\n首先我得先感谢你，若不是你之前手下\n留情，伯约大概早就被拔掉大将军之位。\n&陈祗\n那天若不是尹赏宁可一死，也要慷慨直言\n，姜维的命运早就已经决定了。\n&陈祗\n只是你认为他还能保住大将军的位子？\n&宁随\n不，绝对不可能。\n&宁随\n不过，有件事情要请你考虑的，伯约之后\n，又有谁可以掌兵？\n&宁随\n自从两位吴将军病逝之后，你们这边就\n再也没有可以统兵的人才了。\n&宁随\n相对来说，荆州人那边或许还有阎宇和\n胡济这两个人可以接替。\n&宁随\n只是你愿意让诸葛瞻和董厥这两人的权力\n越来越大？\n&宁随\n董厥先不说，诸葛瞻这样亮眼的政治明星\n应该也给你很大的压力吧。\n&宁随\n朝廷一有好的政策，人民就会自动通告\n说这都是诸葛瞻之所为，试问我们大汉\n除了丞相外，谁有这样的名声？\n&宁随\n你可以轻易拔除庞统的儿子，但是面对\n诸葛瞻，你可完全没有下手的空间。\n&陈祗\n被你说中了…诸葛瞻真是个麻烦人物，\n但是我也没有这个能力打压他，最多只\n能守住自己的位子，避免他往上爬。\n&陈祗\n老实说，我一来不希望把兵权送给你们\n荆州人，二来，我也不认为有人会比姜维\n更能对抗曹贼。\n&宁随\n我可以保证，伯约只要军权，政权交给你\n，就像是之前那样的模式。\n&陈祗\n维持现状是我的期望，也是圣上的期望，\n这点你要记清楚。\n&宁随\n当然，也请你要知道，现在的常败军状况\n非常危险。我们不会放过任何一根可以抓\n的稻草。\n&陈祗\n既然这样，我就愿意当那稻草。\n&宁随\n我就代伯约表示感谢之意。\n&陈祗\n其实还真妙呀，世人都认为姜维和我互通\n声息，却不知道我和他几乎没有见过几次\n面。\n&宁随\n我也很好奇，为什么你会看中伯约？\n&陈祗\n真要说的话，或许是因为他的孤独处境\n和我很像。怎么样？不像是我这种利欲\n薰心的人会说的话？\n&宁随\n不，我相信。\n&陈祗\n嗯…听说姜维也快到成都了，希望这几天\n能看见他亲自进宫面圣。"]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[13]},{"op":"change_scene","args":[2,65535,65535,33,65535]},{"op":"actor_appear","args":[0,34,60,3,1]},{"op":"actor_appear","args":[2,34,52,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["杨兰的安慰"]},{"op":"place_name","args":["成都郊外"]},{"op":"delay","args":[3]},{"op":"dialog","args":["&姜维\n你知道吗？尹兄是我数十年的好盟友，虽\n然他很懦弱，但是他还是会试著鼓起勇气\n去做任何事情。\n&姜维\n只是我没有想到，这次他居然有著我完全\n无法比拟的勇气，敢在所有重臣和圣上前\n面激昂陈辞。\n&姜维\n据说连丞相公子都被他骂到哑口无言。\n&姜维\n我到底做了什么事情？我打了这样难看的\n战争，害死了夏侯将军和关将军，现在甚\n至连尹兄都被我害死。"]},{"op":"delay","args":[3]},{"op":"actor_face","args":[2,0,2]},{"op":"dialog","args":["&杨兰\n乖…乖…想哭就哭，想找人撒娇就找我。"]},{"op":"choice","args":["别开玩笑了！\n………",0]},{"op":"if","cond":"always","args":[],"end":32},{"op":"if","cond":"test_choice","args":[1],"end":24},{"op":"actor_face","args":[0,2,0]},{"op":"dialog","args":["&姜维\n别开玩笑了，我没有这种心情。\n&杨兰\n我什么时候在你面前开过玩笑？"]},{"op":"actor_action","args":[0,0]},{"op":"actor_action","args":[2,3]},{"op":"dialog","args":["&杨兰\n别把自己看这么伟大，这种败仗可不是\n你一个人的力量可以承担的。\n&杨兰\n遗族的怨恨、同僚的嘲讽马上就会排山\n倒海而来，真正的战争才要开始。\n&杨兰\n我杨兰不能帮你别的，但至少可以让你在\n面对责难时，知道自己不是一个人。\n&杨兰\n要是我连这点都做不到，就完全辜负当初\n尹赏的托付了。"]},{"op":"actor_action","args":[2,0]},{"op":"delay","args":[10]},{"op":"dialog","args":["&姜维\n（咦？刚才有这么一瞬间，我还真把她\n看成香了。）"]},{"op":"delay","args":[5]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[2],"end":31},{"op":"set_resource","args":[2,1,10]},{"op":"dialog","args":["&杨兰\n别把自己看这么伟大，这种败仗可不是\n你一个人的力量可以承担的。\n&杨兰\n遗族的怨恨、同僚的嘲讽马上就会排山\n倒海而来，真正的战争才要开始。\n&杨兰\n我杨兰不能帮你别的，但至少可以让你在\n面对责难时，知道自己不是一个人。\n&杨兰\n要是我连这点都做不到，就完全辜负当初\n尹赏的托付了。"]},{"op":"delay","args":[10]},{"op":"actor_face","args":[0,0,0]},{"op":"dialog","args":["&姜维\n（咦？刚才有这么一瞬间，我还真把她\n看成香了。）"]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"delay","args":[3]},{"op":"dialog","args":["&杨兰\n你这次居然故意不在汉中停留，彷彿在\n逃避诸葛果一样。\n&姜维\n……你生气吗？\n&杨兰\n我当然会生气，你平常这么依赖她，\n这时候却又把她丢到一边去。\n&杨兰\n不过呢，这次就原谅你吧，我知道你有你\n的苦衷。\n&姜维\n我已经做了个决定，我想在明天面圣的\n时候，亲自面对所有的责难，并且辞掉\n大将军的职位。\n&杨兰\n无所谓，你做什么我都挺你，反正你就算\n不是大将军，还是可以打仗的。\n&姜维\n我实在是受你太多照顾了。\n&杨兰\n呵呵呵，再多夸赞我一点。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[910]],"end":26},{"op":"play_sound","args":[72]},{"op":"change_scene","args":[2,65535,65535,30,65535]},{"op":"actor_appear","args":[0,50,46,2,0]},{"op":"actor_appear","args":[2,45,46,2,0]},{"op":"actor_appear","args":[563,33,72,1,0]},{"op":"actor_appear","args":[564,33,67,1,0]},{"op":"actor_appear","args":[565,32,61,1,0]},{"op":"actor_appear","args":[573,32,55,1,0]},{"op":"actor_appear","args":[562,34,50,1,0]},{"op":"actor_appear","args":[575,34,44,1,0]},{"op":"actor_appear","args":[574,34,38,1,0]},{"op":"actor_appear","args":[560,37,55,1,0]},{"op":"actor_appear","args":[559,35,33,1,0]},{"op":"actor_appear","args":[571,35,27,1,0]},{"op":"actor_appear","args":[561,35,21,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["蜀人的怨恨"]},{"op":"place_name","args":["成都大街"]},{"op":"dialog","args":["&男子\n姜维！你他妈给我去死啦！\n&农夫\n烂人，你还有脸回来！我的两个儿子都\n死在这场大败中。\n&老妇\n呜呜呜，你还我儿子啊，我儿子不是说\n跟著姜维出征就不会死，怎么会这样？\n&姜维\n………"]},{"op":"actor_face","args":[2,2,3]},{"op":"dialog","args":["&杨兰\n你们别太过分！连鸡蛋都丢过来是怎样！\n&姜维\n杨兰，不要这样，他们都是这场大败的\n受害者，被骂还只是小事而已。"]},{"op":"actor_face","args":[2,0,2]},{"op":"dialog","args":["&杨兰\n这些人真是无理取闹…过去是你是怎么样\n为这个国家奋斗，他们都没看见吗？\n&姜维\n我这点确实远远比不过丞相。\n&姜维\n丞相在北伐失败后，可以马上收拾起一切\n，让人民忘记败战的苦痛，但我却没能力\n做到。\n&杨兰\n丞相是丞相，你是你，这点请你也不要\n忘记了。\n&姜维\n是呀…\n&杨兰\n真讨厌耶！那鸡蛋真的超难洗的！"]},{"op":"delay","args":[8]},{"op":"endif","args":[]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[46]},{"op":"change_scene","args":[2,65535,65535,50,65535]},{"op":"actor_appear","args":[49,52,77,0,0]},{"op":"actor_appear","args":[50,59,73,0,0]},{"op":"actor_appear","args":[51,39,61,1,0]},{"op":"actor_appear","args":[55,39,56,1,0]},{"op":"actor_appear","args":[652,39,51,1,0]},{"op":"actor_appear","args":[42,39,46,1,0]},{"op":"actor_appear","args":[40,65,61,3,0]},{"op":"actor_appear","args":[47,65,56,3,0]},{"op":"actor_appear","args":[257,65,51,3,0]},{"op":"actor_appear","args":[707,65,46,3,0]},{"op":"actor_appear","args":[0,49,61,2,0]},{"op":"actor_appear","args":[198,55,61,2,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["最终的处置"]},{"op":"place_name","args":["成都 皇宫"]},{"op":"dialog","args":["&刘禅\n关于执金吾的事情，朕感到万分遗憾。"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n微臣认为尹兄并无遗憾，他能够在一生的\n最后一刻克服他心中的恐惧，已经不会有\n遗憾了。\n&董厥\n所谓的满足，就是在朝堂之上大呼小叫？\n&刘禅\n执金吾的事情，朕都已经原谅他了，难道\n尚书仆射你还要耿耿于怀？"]},{"op":"actor_action","args":[0,0]},{"op":"actor_face","args":[47,6,2]},{"op":"dialog","args":["&董厥\n臣不敢…"]},{"op":"actor_face","args":[47,0,3]},{"op":"delay","args":[5]},{"op":"dialog","args":["&刘禅\n朕听说这次会损失如此惨重，和镇西\n大将军行军延滞有关，所以特地找他\n来和大将军对质。\n&胡济\n臣…"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n没有这回事，所有的责任都在微臣。\n&姜维\n是微臣不见好就收，深入敌阵多时，\n造成补给困难，最后才害我军有这样\n下场。\n&胡济\n（伯约，这次我真的对不起你。）\n&陈祗\n（这个姜维也真是的，明明圣上就已经\n有意要维护他，现在他却自愿放弃。）\n&陈祗\n（不过若是姜维把所有责任都推给胡济，\n恐怕他也会和荆襄人正式决裂，到时候他\n也没多好过。）\n&姜维\n（我心中还是有怨恨，但至少胡济他还是\n经历过丞相北伐的世代。若换成其他人，\n难说会不会支持再度用兵。）"]},{"op":"actor_action","args":[0,0]},{"op":"actor_face","args":[51,6,2]},{"op":"if","cond":"test_flags","args":[[910],[]],"end":33},{"op":"dialog","args":["&陈祗\n臣以为，大将军这次虽然造成我军重大\n损失，但也给敌人相当的打击，若说有\n过错，也不至于太严重。\n&陈祗\n因为这样的小过就处置我国军事的栋梁，\n这样不是称了贼营的心？"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[910]],"end":36},{"op":"dialog","args":["&陈祗\n这次大将军虽然大败，但自古以来名将\n何人没有遭逢败绩？纵是丞相也有街亭\n一败。\n&陈祗\n因段谷一败就忘记洮西大捷，这实在不是\n我们应该对待大将军这样人才的态度。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&谯周\n（陈祗这家伙！只要他在一天，陛下就会\n继续被蒙蔽去支持姜维。）\n&诸葛瞻\n（陈祗这个家伙，居然和姜维狼狈为奸，\n有这两人把持朝政，爹苦心经营的大汉政\n风将毁于一旦。）\n&诸葛瞻\n（费叔叔一时看走眼，让这样的奸人当道\n。我真恨自己现在没有更大的权力，不然\n我一定会立刻为国除奸。）"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n陛下，微臣希望自贬三等，来表示对\n这件事负责。\n&董厥\n哼，连这点都和丞相学，有点创意好吗？\n&刘禅\n好吧。\n&刘禅\n姜维出师不利，在段谷一战丧师辱国，\n即刻贬为后将军。\n&诸葛瞻\n（好呀，终于把这个穷兵黩武的疯子\n赶下来了。）\n&刘禅\n但朕仍认为姜维为国家不可或缺的栋梁，\n所以命其以后将军行大将军事。\n&姜维\n陛下…\n&刘禅\n朕相信你，就像过去相信相父那样。\n&姜维\n臣一定为大汉誓死效忠！\n&诸葛瞻\n……"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[0]},{"op":"change_scene","args":[2,65535,65535,61,65535]},{"op":"actor_appear","args":[0,53,63,1,0]},{"op":"actor_appear","args":[51,58,63,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["坦诚相见"]},{"op":"place_name","args":["成都尚书令府"]},{"op":"dialog","args":["&陈祗\n老实对你说，胡济的援军是我按下来的，\n目的是希望让你打败仗，压制你的气焰。\n&姜维\n我大概也猜到了，只差向来忠证实而已。\n&陈祗\n感觉我很恐怖？为了巩固自己的地位，\n让上千的大汉将士送命都在所不惜。\n&姜维\n我确实很愤怒，但是我却没有资格怪你。\n是我自己不识敌情，冒著断粮危险驻屯于\n敌境。\n&陈祗\n嗯…你真是个让人捉摸不定的人…\n&陈祗\n我已经在你的面前表现出我的本性，一个\n贪婪又自私，可以为了自己的私利牺牲掉\n任何人。\n&陈祗\n但是你呢？你究竟是什么样的人？\n&陈祗\n你执意要率军北伐究竟是为何？为了丞相\n的知遇之恩？还是个人的名利？\n&姜维\n都是也都不是。\n&姜维\n我并非完全无私之完人，一样希望能够\n升官晋爵。\n&姜维\n只要北伐大业能完成，既可实现丞相的\n梦想，回报丞相恩情，也可使自己功成\n名就，我认为这些没有冲突。\n&陈祗\n嗯…果然我还是搞不懂你。\n&陈祗\n不过，比起其他有太多背景的将领，\n我还是想要和你合作。\n&陈祗\n你没有拒绝的权力，在现在的情况下，\n和我合作是你生存的唯一之途。\n&陈祗\n你鄙视我也好，怨恨我也好，要成就大事\n你就得忍耐。\n&陈祗\n你习惯和君子相处，也得学会和小人共事\n，这是我给你的最好建议。\n&姜维\n我明白了。\n&陈祗\n毫不犹豫就答应？你该知道我是声名狼藉\n的小人吧。\n&姜维\n就算如此，我还是看见你充满算计的外表\n下，有个想要做一番事业的心。"]},{"op":"delay","args":[8]},{"op":"actor_face","args":[51,0,1]},{"op":"dialog","args":["&陈祗\n真可笑，像我这种和黄皓互为表里的小人\n会有什么大志？\n&姜维\n你的外祖父许司徒名满天下，就连丞相\n见了他都要下拜。\n&姜维\n身为外孙的你没有道理不想效法他，成为\n天下传颂的名士。\n&陈祗\n你知道那样的名士曾经被先帝鄙视？他在\n曾经对他有恩的刘璋困顿时，居然第一个\n逃跑。\n&陈祗\n先帝重用他不过是认为他有名声罢了。\n&姜维\n我不这么认为，如果许司徒真的空有名声\n，那么先帝不会在即位之时还让他担任\n大汉建国以来唯一的三公。\n&姜维\n他用自己的行动来洗刷污名，用更积极\n的表现证明自己非虚有其表。\n&姜维\n纵然一时失足，然不能掩饰司徒是大汉\n第一名士的光彩。\n&陈祗\n回到前线去吧，那里才是你该奋斗的\n地方，后方的战斗自有人在负责。\n&姜维\n（其实奉宗说的也没有错呀，我把政治\n这件事情看简单了。没有他在成都的运\n作，只怕我早就被陛下舍弃。）\n&姜维\n（不过纵然如此，我还是不想要跨越\n那条线，当一个人手握军政大权，就\n只能走上不归路了。）\n&陈祗\n（我现在明白为什么丞相会对这个外人\n这么另眼相看，他心中总是有些与众不同\n的观点。）\n&陈祗\n（我纵然得到陛下的信任，但还是不足以\n像丞相那样只手遮天。所以我必须要外联\n姜维，内结黄皓。）\n&陈祗\n（其实默许这样政体运作的，不就是陛下\n吗？外人看我操弄权势，其实我是投陛下\n所好，让他能够放心。）\n&陈祗\n（我们都是陛下手上的玩物，但是不想当\n玩物就得成为司马懿或孙峻，难道就没有\n解决之道？）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[57]},{"op":"change_scene","args":[2,65535,65535,3,65535]},{"op":"actor_appear","args":[1,60,57,3,0]},{"op":"actor_appear","args":[19,54,60,1,0]},{"op":"actor_appear","args":[18,54,54,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["诸葛果的行动"]},{"op":"place_name","args":["汉中诸葛家"]},{"op":"dialog","args":["&赵统\n不知道诸葛姑娘找我们兄弟俩有什么\n事情？\n&诸葛果\n我想要去寿春一趟，需要两位的同行。\n&赵统\n什么？！寿春？\n&赵广\n（诸葛姑娘开口永远是让人惊奇。）\n&诸葛果\n原因到时候再说，两位可否答应同行？\n&赵统\n我想要知道原因！"]},{"op":"actor_face","args":[19,0,1]},{"op":"dialog","args":["&赵广\n我倒认为诸葛姑娘这样说，一定有她的\n用意在，不如答应吧。\n&赵统\n不行，这次我一定要听到理由！\n&赵广\n（大哥的固执脾气，真是像透了爹。）"]},{"op":"delay","args":[8]},{"op":"actor_appear","args":[214,29,59,1,0]},{"op":"actor_face","args":[18,0,3]},{"op":"actor_face","args":[19,0,3]},{"op":"dialog","args":["&黄月英\n我的女儿有话经常都不说，就由我来说\n吧。\n&黄月英\n我们诸葛家有个亲戚人在寿春，女儿想要\n去拜访他而已。\n&赵统\n亲戚？\n&赵广\n我好像有听过一个叫做诸葛诞的…\n&黄月英\n小赵将军果然聪明，确实就是要去拜访\n他。\n&诸葛果\n娘，不阻止我？\n&黄月英\n如果我阻止你，你心中的罪恶感永远不会\n消除，这样反而是害了你。\n&黄月英\n只是，我从来没有听孔明说过关于他那位\n族弟的事情，你对于他了解多少？\n&诸葛果\n根据杨姑娘从毌丘俭等人口中听来的说法\n，我大概可以知道他是什么样的人。\n&黄月英\n为了大汉或是姜维，你真的已经下定决心\n要做这种事？你有背负诸葛诞性命的觉悟\n了吗？\n&诸葛果\n父亲说过，人一生只能杀一个人…我已经\n有觉悟了…\n&黄月英\n好！过去我也曾经为孔明背负过一条人命\n，或许这就是诸葛家的宿命吧。\n&黄月英\n那么两位赵将军，愿意陪小女去吗？"]},{"op":"delay","args":[8]},{"op":"actor_action","args":[18,6]},{"op":"actor_action","args":[19,6]},{"op":"dialog","args":["&赵统\n我听傅佥说过，贼营那边有许多非常厉害\n的高手，我也想见识一下。\n&赵广\n我从来没有踏上过贼营的领土，这次能够\n增广见闻也是好事。\n&黄月英\n那么就有劳二位了。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[9]},{"op":"change_scene","args":[2,65535,65535,73,65535]},{"op":"actor_appear","args":[127,46,53,2,0]},{"op":"actor_appear","args":[128,43,58,0,0]},{"op":"actor_appear","args":[129,50,58,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["文钦的壮志"]},{"op":"place_name","args":["河边"]},{"op":"dialog","args":["&文钦\n我们来到这里有多久了？\n&文虎\n大概有一年了吧。\n&文钦\n才一年？对我来说像过了十年一样。\n&文钦\n四十年前，因为魏讽案牵连，若不是武帝\n看我是功臣之子赦免我，我早就没命。\n&文钦\n我这条命是武帝给的。除了报答昭伯、\n仲恭的知遇之恩，我所做的一切，更是\n为了回报武皇帝当年的恩情！\n&文钦\n这一年来，想到仲恭对我说过的话，我就\n恨不得马上回去和司马家拚个你死我活。\n&文虎\n爹，孩儿实在是感佩您重情义的表现。\n&文鸯\n爹，您在这边也该注意到一些事情吧。\n&文鸯\n这边的政治斗争激烈程度，丝毫不输过去\n的大魏。\n&文鸯\n目前我们很得孙峻信任，但是万一他倒下\n来呢？这里政变频繁，什么事情都会发生\n的。\n&文钦\n所以我才请求孙峻发兵北伐，我想趁著他\n还当权的时候，尽快了却我的心愿。\n&文鸯\n说得也是，他有著不得不答应的理由。\n&文钦\n他现在的权力基础很薄弱，只不过是靠著\n和全家的结合，勉强取得优势，然而他没\n有本事完全排除其他有力人士。\n&文钦\n只有靠著建立自己的战功，才能够让自己\n的权力正当化，也才能堵住其他人的嘴。\n&文虎\n父亲真是见多识广。\n&文鸯\n想不到我们来到这边以后，反而更难在\n战场上放手一搏。\n&文钦\n阿鸯，我也不希望变成这样。\n&文钦\n当初我也瞧不起那些看当权者脸色吃饭的\n将领，结果我在这边也变成这样的人。\n&文钦\n这样的环境实在是不能久留，纵然我们\n获得高官显爵，终究会腐蚀我们的内心。\n&文鸯\n那么等到北伐的时候再杀个痛快就好了，\n这次我可不会放过小昭昭。\n&文钦\n有这样的志气，真不愧是我文钦的儿子。"]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[9]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,29,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["东吴镇北大将军文钦，向丞相孙峻分析攻打曹魏的好处，终于获得出兵的许可。",1,0,1]},{"op":"delay","args":[5]},{"op":"caption","args":["文钦和骠骑将军吕据、车骑将军刘纂、镇南将军朱异、前将军唐咨等，",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["从江都进入淮泗一带，准备攻击曹魏的青州和徐州地区。",0,0,1]},{"op":"delay","args":[5]},{"op":"caption","args":["然而，文钦的北伐美梦，却在孙峻得到急病后，出现了重大变数…",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[4]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,5,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"title_text","args":["私相授受"]},{"op":"place_name","args":["石头城 临时丞相府"]},{"op":"dialog","args":["&孙綝\n听到您急急忙忙召我过来，我大概就知道\n发生什么事情了，只是没想到事情会这么\n严重。\n&孙峻\n我梦见…诸葛恪殴打我，等到醒来的时候\n…我就已经动不了了…\n&孙綝\n诸葛恪那个逆贼，到死都还要作怪！\n&孙峻\n那不是…重点…重点是…现在只有你…\n知道我…病倒的消息…\n&孙綝\n这是为什么？为什么不让准备出发的骠骑\n将军或是司徒知道？\n&孙峻\n孙家的权力…终归…只能给…孙家人…\n&孙峻\n哪怕…是那些人…联合起来…反抗…也在\n所不惜…\n&孙綝\n我只是宗室疏属，位低权轻，更非顾命\n大臣，没有资格超前于吕据、滕胤，更\n不敢打破大皇帝遗留的体制。\n&孙峻\n蠢啊！如果大皇帝的体制无法保卫大吴？\n&孙綝\n（从兄怎么又恢复活力了？！）\n&孙峻\n看看北方，曹睿让宗室曹爽与异姓司马懿\n共同担任托孤大臣，结果司马家反过来\n吞食曹家。\n&孙峻\n大皇帝当初托孤于我与四位异姓，结果那\n个诸葛恪差点变成第二个司马懿，若不是\n我果断下手，现在早就变诸葛家专政。\n&孙峻\n我把权力集中给自己，滕胤、吕据却不说\n话，难道他们无欲无求？八成是肖想大皇\n帝的遗诏，想等我死后接收我的权位。\n&孙峻\n所以我要破坏遗命，只有把权力交给孙家\n人，才能确保孙家安全无虞。就算最后宗\n室相残，胜利者都是孙家人。\n&孙峻\n你一定会遇到很多挑战，绝对要果断。\n&孙峻\n曹爽傻傻地想让司马懿自然老死，还被\n七十一岁的老头反扑，何况吕据他们跟\n我年纪相近。\n&孙峻\n要是你被打倒，以后孙吴宗室的地位恐怕\n就要一落千丈了\n&孙綝\n从兄，我真的能够担当这样的重任？\n&孙峻\n我已经向圣上请求任命你都督中外诸军事\n，只要有兵权，你谁都不需要怕…\n&孙綝\n我明白了，这就依照从兄的吩咐，我将\n继承从兄的地位。\n&孙峻\n记得要照顾…大虎…她…在我…死了以后\n…会很寂寞…\n&孙綝\n没问题！\n&孙綝\n（搞什么东西，弄到最后居然只是想\n找个人来帮他照顾那个孙大虎。）\n&孙綝\n（我实在是不懂，这种年纪的阿婆有什么\n吸引力可言。）\n&孙綝\n（这么老的也有兴趣，是因为牛肉面\n煮得好？）\n&孙峻\n诸葛恪？！你怎么又过来了？！不要！"]},{"op":"delay","args":[8]},{"op":"dialog","args":["&孙綝\n从兄，什么人都没有呀？\n&孙峻\n不要啊！不要啊！诸葛恪，不是我想杀你\n，实在是没有别的选择啊…\n&孙峻\n………"]},{"op":"delay","args":[8]},{"op":"caption","args":["公元二五六年，丞相孙峻去世后，把权力交给偏将军孙綝，",0,0,1]},{"op":"delay","args":[8]},{"op":"caption","args":["孙綝被任命为侍中、武卫将军、都督中外诸军事。",1,1,1]},{"op":"delay","args":[8]},{"op":"caption","args":["孙綝上任后随即召回进军中的吕据，然而，这样私相授受的人事安排，",0,0,1]},{"op":"delay","args":[8]},{"op":"caption","args":["开始在东吴政界掀起反弹的声浪。",1,1,1]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[72]},{"op":"change_scene","args":[2,65535,65535,21,65535]},{"op":"actor_appear","args":[177,48,67,0,0]},{"op":"actor_appear","args":[127,61,54,3,0]},{"op":"actor_appear","args":[128,61,49,3,0]},{"op":"actor_appear","args":[129,61,44,3,0]},{"op":"actor_appear","args":[173,61,39,3,0]},{"op":"actor_appear","args":[181,36,54,1,0]},{"op":"actor_appear","args":[179,36,49,1,0]},{"op":"actor_appear","args":[180,36,44,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["吕据之怒"]},{"op":"place_name","args":["吴军营帐"]},{"op":"dialog","args":["&吕据\n孙綝算什么东西？！小小一个偏将军也敢\n来下令我班师？"]},{"op":"actor_face","args":[179,6,2]},{"op":"dialog","args":["&唐咨\n不管怎么说，他现在也有军权，难道我们\n不听他的话？\n&吕据\n笑话！这样的人事任命有什么正当性可言\n？孙峻他凭什么把权力传给他从弟？\n&吕据\n当初我们几个人都是大皇帝任命的顾命\n大臣，他死了就该把权力交出来，怎么\n可以给一个没有顾命大臣身份的人！\n&吕据\n现在我决定要上书朝廷，推举司徒滕胤当\n丞相，也希望各位的帮忙。\n&文钦\n（为什么事情会变成这样？北伐就差这\n一步，居然又卷进这样丑陋的斗争中。）\n&朱异\n（你们打死好了，反正这边大都是北方人\n，那边的孙家也不过是吴郡三流家族，我\n吴郡朱家没必要和你们耗。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["吕据和麾下将领联名上书，推荐司徒滕胤\n担任丞相。然而孙綝却改命滕胤当大司马\n，并且派往镇守武昌。\n\n吕据知道后更是大怒，立刻派人通知滕胤\n，要求联合罢黜孙綝。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[4]},{"op":"change_scene","args":[2,65535,65535,45,65535]},{"op":"actor_appear","args":[165,49,48,1,0]},{"op":"actor_appear","args":[220,55,48,3,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["柴桑议事厅"]},{"op":"title_text","args":["东吴激变"]},{"op":"dialog","args":["&陆抗\n小甘宁，最近发生的这件事情，你有什么\n看法？\n&甘宁\n我没兴趣知道那种无聊的事情，快点陪我\n玩，不然我会很无聊，无聊到想要写周瑜\nｘ鲁肃的男男小说…想看？\n&陆抗\n我想要跟另一个小甘宁说话，拜托你可以\n不要搅局吗？\n&甘宁\n真扫兴…你明知道在战场以外的地方叫\n她会很危险的…好吧，谁叫你是陆逊的\n儿子。"]},{"op":"delay","args":[10]},{"op":"dialog","args":["&甘宁\n什么事情吗？\n&陆抗\n这件事情你不觉得是件不得了的大事？\n&甘宁\n那又如何？你我人微言轻，既不能有所\n作为，也不至于受害，这样不就好了。\n&陆抗\n可是我大吴从大皇帝崩殂以来，内斗杀戮\n不断，这样下去，大吴真的会很危险。\n&甘宁\n动动脑子吧，你吴郡人有什么理由去淌这\n浑水？\n&甘宁\n当初那帮子北方人撑过了二宫之变，欺压\n因为二宫之变而伤亡惨重的江东士族，把\n政权整碗捧去。\n&甘宁\n现在他们像呆子一样杀来杀去，对你不正\n是好事？\n&陆抗\n这样说来，也不是没有道理…不过缺乏\n权力继承正当基础的孙綝，为了保护自己\n，恐怕会把屠刀伸向任何靠近他的人。\n&陆抗\n所以我该让陆家人在这个时候从他眼前\n消失，不然卷进危险就不得了。\n&甘宁\n看来你也认为孙綝会赢？\n&陆抗\n嗯…因为孙綝的政治斗争经验，比起吕据\n或是滕胤要丰富很多，那两个人虽然比较\n有才干，但是斗争却是外行。\n&陆抗\n我想不出一个月，孙綝必定发动反击。\n&陆抗\n（当年大皇帝对我们吴四姓动手，我们退\n出权力中心反而躲过这几年的浩劫。这样\n祸福相倚真是讽刺。）"]},{"op":"delay","args":[10]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[4]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,25,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["果然不出陆抗所料，孙綝对于吕据和滕胤的行动，展开激烈的反击。",1,0,1]},{"op":"delay","args":[8]},{"op":"caption","args":["首先他命族兄孙宪，率军北上拦截吕据北伐军。",0,0,1]},{"op":"caption","args":["接著又派侍中华融和中书丞丁晏，劝告滕胤即刻离开建业。",1,1,1]},{"op":"delay","args":[8]},{"op":"caption","args":["滕胤认为这是孙綝的诡计，拒绝就任，并且扣留住丁晏和华融两人，率众抗战。",0,0,1]},{"op":"caption","args":["滕胤一方面指控孙綝谋反，一方面强迫华融写信给孙綝，劝告他退位。",1,1,1]},{"op":"delay","args":[8]},{"op":"caption","args":["孙綝拒绝，上书皇帝孙亮，指控滕胤谋反，并且派兵攻击滕胤。",0,0,1]},{"op":"caption","args":["滕胤见状也命丁晏和华融两人假传圣旨，徵召各军，两人不从，当场被斩。",1,1,1]},{"op":"delay","args":[8]},{"op":"caption","args":["此时，孙綝的军队已经逼进滕胤府中，双方在建业的会战一触即发。",0,0,1]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[72]},{"op":"change_scene","args":[2,65535,65535,8,65535]},{"op":"actor_appear","args":[590,34,53,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["滕胤遇害"]},{"op":"place_name","args":["建业司徒府"]},{"op":"dialog","args":["&滕胤\n（我既然已经斩了两位孙綝的心腹，现在\n情况已经是骑虎难下，我也不能回头再去\n投降孙綝了。）\n&滕胤\n（虽说有人建议我进军苍龙门，但是我\n这样逼宫，又和孙峻或是孙綝这两个人\n有什么两样呢？）\n&滕胤\n（现在只有等世议的大军赶到，\n我们再会师诛除这个逆贼。）"]},{"op":"delay","args":[8]},{"op":"actor_appear","args":[163,96,57,3,0]},{"op":"actor_appear","args":[258,92,52,3,0]},{"op":"actor_appear","args":[259,92,61,3,0]},{"op":"actor_move","args":[0,163,0,82,57,3]},{"op":"actor_move","args":[0,258,0,87,52,3]},{"op":"actor_move","args":[0,259,0,87,61,3]},{"op":"actor_action","args":[162,0]},{"op":"actor_action","args":[258,0]},{"op":"actor_action","args":[259,0]},{"op":"delay","args":[8]},{"op":"dialog","args":["&滕胤\n怎么会是你？我的部下呢？\n&孙綝\n他们全都跑光，因为你所期盼的吕据大军\n不会来了。\n&滕胤\n什么？！"]},{"op":"actor_action","args":[163,2]},{"op":"dialog","args":["&孙綝\n蠢货！你以为你斗得过我？如果你知道\n吕据军队无法赶过来，绝对不会像刚才\n那样，还谈笑自若呢。\n&滕胤\n真可恨，早在孙峻升任丞相，却又不设置\n御史大夫的时候，我就应该挺身反抗孙峻\n这家伙。"]},{"op":"actor_action","args":[163,0]},{"op":"dialog","args":["&孙綝\n你和吕据还不是想著，孙峻死后，大吴就\n是你们的天下？却没有想过，族兄早就有\n所安排。\n&滕胤\n我如果这样想的话，当初我早就参加诛杀\n诸葛恪的行动，别把我和你们孙家的小人\n相提并论！\n&滕胤\n我只恨我看走眼，认为孙峻可以拨乱反正\n，可以阻止诸葛恪的狂乱，所以对他的行\n动，保持沉默。\n&滕胤\n没想到，最后我和吕据沉默的代价，是\n养出你们两个比诸葛恪狂暴十倍的怪兽！\n&孙綝\n随你怎么说，反正你今天要死的命运是\n不会改变的。"]},{"op":"actor_action","args":[590,0]},{"op":"dialog","args":["&滕胤\n哼哼哼，大皇帝在天之灵，会好好看著你\n这个孙家的败类，总有一天会给你最残酷\n的报应。"]},{"op":"delay","args":[8]},{"op":"dialog","args":["孙綝率军攻入滕胤府中，滕胤和他部属数\n十人都被当场格杀。接著，孙綝又屠杀滕\n胤三族。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[72]},{"op":"change_scene","args":[2,65535,65535,21,65535]},{"op":"actor_appear","args":[177,48,67,0,0]},{"op":"actor_appear","args":[127,42,50,2,0]},{"op":"actor_appear","args":[179,50,50,2,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["吕据之死"]},{"op":"place_name","args":["吴军营帐"]},{"op":"dialog","args":["&吕据\n看见你们两个，我对于自己的下场也该\n明白了。\n&唐咨\n所有的北伐军将士都不会效忠你，大家\n决定听从圣上讨伐叛贼的诏令。\n&吕据\n我吕家两代忠心为孙家。\n&吕据\n我爹吕范愿意把所有的希望投注在当时\n仍然寄人篱下的长沙桓王（孙策），将\n门下食客百余人都让给他。\n&吕据\n我爹后来奉命去迎接武烈皇后（吴国太）\n，哪知道被陶谦当作是袁术的间谍，遭到\n严刑拷打，最后还是能完成使命。\n&吕据\n之后爹随著长沙桓王平定江东，又帮助\n大皇帝安定后方，临死前还一直嘱托我\n要为大吴效忠，请问我可能当个叛贼？\n&文钦\n我知道你是委屈的，但是现在的情况，\n已经不是用道理可以说得清的。\n&吕据\n我知道，我并不怪你，你有更重要的事情\n要去完成，不可以死在这里。\n&文钦\n（我还要为仲恭复兴魏室 怎能死在这里\n？无论如何都要生存下来，哪怕是被当\n成懦夫也好。）\n&文钦\n（忍耐到获得更重大的胜利为止，这些\n都是你教我的，对吧，仲恭？）\n&吕据\n反而是唐咨你这个家伙，来来回回已经\n叛变了多少次？人说吕布三姓家奴，你都\n已经几姓了？\n&吕据\n这次倒戈到孙綝那，我想对你来说也不算\n什么吧。\n&唐咨\n哼，死到临头还嘴炮什么。\n&文钦\n世议，趁现在逃到魏国吧，我想以你的\n身分，司马昭没有拒绝你的理由。\n&唐咨\n（哼，你说我多姓家奴，我就看你面对\n生死存亡关头又会怎么做？）\n&吕据\n不了，吕据以吕家的忠义为傲，我绝对\n不会做叛徒。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["吕据说完随即自杀，之后孙綝仍然将吕据\n三族屠灭。自此，孙权临终前任命的所有\n托孤重臣，全部不在人世间了。\n\n两个最大的威胁消失后，孙綝开始总揽朝\n政，不久后被任命为大将军，成为东吴新\n一代权臣。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[71]},{"op":"change_scene","args":[2,65535,65535,11,65535]},{"op":"actor_appear","args":[130,49,71,0,0]},{"op":"actor_appear","args":[199,36,55,1,0]},{"op":"actor_appear","args":[100,36,50,1,0]},{"op":"actor_appear","args":[102,36,45,1,0]},{"op":"actor_appear","args":[103,63,55,3,0]},{"op":"actor_appear","args":[106,63,50,3,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["司马家的新敌人"]},{"op":"place_name","args":["洛阳大将军府"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&司马昭\n公闾，这次请你前往寿春一趟，感想\n如何？"]},{"op":"actor_face","args":[100,6,2]},{"op":"dialog","args":["&贾充\n诸葛诞会成为我们的敌人！\n&司马昭\n果然…虽说他和我们司马家有姻亲关系，\n终究他还只是个旧时代的人。\n&司马昭\n我请你问的问题是不是太过刺激了？连\n诸葛诞这种对我们司马家有好感的人都\n翻脸了，更何况你呢？\n&贾充\n大将军，在下已经决定要站到您这边了\n，对于那个问题，在下的答案您该明白。\n&荀勖\n（我们哪有挑边站的权利？现在既然已经\n跳上贼船，也只有舍命跟到底了。）\n&师纂\n（外敌都铲除乾净了，现在就开始针对\n自己人下手，看来是轮到诸葛诞了。）\n&裴秀\n（钟会这家伙因为母丧而缺席，看来现在\n正是我等表现的大好机会。）\n&贾充\n诸葛诞两度镇守扬州，深受部属和人民\n爱戴，这是非常大的隐忧。\n&贾充\n在下建议徵召他回京师，剥夺他的军权。\n&司马昭\n还想给他最后一次机会？你的心还真软。\n&贾充\n不，在下认为他一定叛变。然今日叛变，\n灾祸较小，否则拖延下去，灾祸大不可测\n，不如今天了断。\n&司马昭\n说得也是，事情就交给你办了。\n&司马昭\n公闾，经过这一次的事情，我可以放心把\n司马家的背后交给你了。\n&司马昭\n过去我爹想结交贾逵而终身不可得，今日\n我结交他的儿子，也算是完成爹的梦想了\n吧。"]},{"op":"actor_action","args":[130,6]},{"op":"dialog","args":["&司马昭\n来，公闾，我敬你一杯。\n&贾充\n是！\n&贾充\n（爹啊，就算您责备我丢了贾家的人，\n我还是得这样做，我要保护贾家上上下下\n数十口人的性命啊。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[30]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[95,29,54,1,0]},{"op":"actor_appear","args":[131,48,41,2,0]},{"op":"actor_appear","args":[132,48,69,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["诸葛诞的困惑"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"dialog","args":["&诸葛诞\n我这几年来，到底在做什么？我到底做了\n什么事情？\n&蒋班\n（怎么回事呀？）\n&焦彝\n（我也不知道，似乎从上次贾充来访后，\n镇东将军就变成这副德行。）\n&诸葛诞\n昭伯，太初，平叔…为什么我到现在才\n明白你们的心？为什么我到现在才看清\n司马家的真面目？然而这一切都太迟了。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[71]},{"op":"actor_appear","args":[95,29,54,1,0]},{"op":"actor_appear","args":[100,48,54,3,0]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"fade_out","args":[]},{"op":"title_text","args":["半个月前"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[100,6]},{"op":"dialog","args":["&贾充\n在下听说洛阳许多人都希望皇上禅让，\n不知您怎么看？\n&诸葛诞\n你说什么？禅让？\n&贾充\n是的，就是禅让。\n&诸葛诞\n（原来司马昭真的想篡位？我一直在助纣\n为虐？他们竟然欺骗我这么久。）\n&诸葛诞\n（身为名士，识人之明居然还比不上那\n粗鲁的文钦。）\n&诸葛诞\n（太初、平叔一定也在笑我。作为四聪\n八达最后一人，不能这样苟且偷生！）"]},{"op":"actor_action","args":[95,0]},{"op":"dialog","args":["&诸葛诞\n你不是贾逵的儿子？！世代都受到大魏的\n恩惠，怎么可以把政权送给别人？\n&贾充\n别激动，在下也只是听别人说的。\n&诸葛诞\n告诉你！如果洛阳政变，我当以死报答。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[30]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[95,29,54,1,0]},{"op":"actor_appear","args":[131,48,41,2,0]},{"op":"actor_appear","args":[132,48,69,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["诸葛诞的困惑"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[722,95,54,3,0]},{"op":"actor_move","args":[0,722,0,48,54,3]},{"op":"actor_action","args":[722,6]},{"op":"dialog","args":["&诸葛靓\n爹，看您最近愁眉苦脸的样子，要不要\n出去透透气？\n&诸葛诞\n我哪有这个心情。\n&诸葛靓\n我听说最近寿春来了个非常灵验的算命师\n，听说比我们的神算章鱼“宝锣”还准，\n爹要不要也去给他看一下？\n&蒋班\n什么术士这么跩？叫过来就好了。\n&诸葛靓\n不不不，那个半仙可不愿意随便给人看相\n，如果不让他满意，怎么样都叫不过来。\n&诸葛诞\n也好，就让我去看看吧。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[57]},{"op":"change_scene","args":[2,65535,65535,65,65535]},{"op":"actor_appear","args":[567,37,66,1,17]},{"op":"actor_appear","args":[568,59,66,3,17]},{"op":"actor_appear","args":[569,53,66,1,0]},{"op":"actor_appear","args":[572,53,72,1,0]},{"op":"actor_appear","args":[574,55,78,1,0]},{"op":"actor_appear","args":[576,57,83,1,0]},{"op":"actor_appear","args":[573,54,88,1,0]},{"op":"actor_appear","args":[564,47,75,1,0]},{"op":"actor_appear","args":[575,44,80,1,0]},{"op":"actor_appear","args":[18,69,50,2,0]},{"op":"actor_appear","args":[19,75,50,2,0]},{"op":"actor_appear","args":[1,72,54,2,0]},{"op":"actor_appear","args":[95,72,60,0,0]},{"op":"actor_appear","args":[722,72,66,0,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["寿春神算"]},{"op":"place_name","args":["寿春城城门"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&诸葛靓\n爹，就是这里。\n&诸葛诞\n真没想到，所谓的神算…居然是个女人。"]},{"op":"actor_action","args":[1,6]},{"op":"dialog","args":["&诸葛果\n只要算得准，不管男人或是女人都无妨。"]},{"op":"actor_action","args":[1,0]},{"op":"dialog","args":["&诸葛诞\n说得也是…只是你真的如传说中算得\n那么准？\n&诸葛果\n正始名士所剩无几，四聪八达只余一人。\n&诸葛诞\n你究竟是什么人？\n&诸葛果\n你现在走在命运的交叉点上，你充满著\n彷徨和犹豫。\n&诸葛果\n究竟是要成为忠臣，还是要成为开国功臣\n，你的心中还在摆荡。\n&诸葛诞\n………\n&诸葛诞\n我看你不是神算，而是利用神算的名号\n想要吸引我过来见你。\n&赵统\n（真的如她说的，诸葛诞会上勾。）\n&赵广\n（我就说听诸葛姑娘的准没错。）\n&诸葛果\n不久之后，会发生一件逼迫你要做出决定\n的事情，我正是为了帮助你做出正确决定\n而来的。\n&诸葛诞\n呵呵…可以告诉我，你究竟是谁了吧。\n&诸葛果\n琅邪诸葛家，一门三方为冠盖，天下\n荣之。\n&诸葛诞\n（等一下，如果说她也和诸葛家有关系的\n话，扣除掉已经灭门的东吴诸葛家，那么\n就只剩下蜀地…）\n&诸葛诞\n（该不会…她和那个名满天下的从兄有\n关系？）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[34]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[95,29,54,1,0]},{"op":"actor_appear","args":[131,48,41,2,0]},{"op":"actor_appear","args":[132,56,41,2,0]},{"op":"actor_appear","args":[1,48,69,0,0]},{"op":"actor_appear","args":[722,56,69,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["寿春三叛"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"dialog","args":["&诸葛诞\n真是没有想到，能够在这里见到从未谋面\n的蜀地诸葛家人。"]},{"op":"actor_face","args":[131,0,3]},{"op":"dialog","args":["&蒋班\n这样好吗？虽说眼前是个看起来没有威胁\n性的弱女子，但她是蜀人也是事实。\n&诸葛诞\n那又如何？她是我的亲戚，过去我想见\n从兄而不可得，现在能见到他女儿也算\n得偿所愿。\n&焦彝\n（平白无故跑来这边，一定有问题。不过\n，既然是蜀人，应该也不会去劝将军效忠\n司马家，可以好好观察一下。）\n&诸葛诞\n等一下，似乎有人来了…"]},{"op":"actor_face","args":[131,0,2]},{"op":"delay","args":[5]},{"op":"play_sound","args":[31]},{"op":"actor_appear","args":[566,95,54,3,0]},{"op":"actor_move","args":[0,566,0,48,54,3]},{"op":"actor_action","args":[566,6]},{"op":"dialog","args":["&士兵01\n恭喜镇东将军！\n&诸葛诞\n有什么事情好恭喜的？\n&士兵01\n朝廷徵召您回到洛阳担任司空，能够升到\n三公位置，小人还能不恭喜？\n&诸葛诞\n朝廷有说什么时候出发？\n&士兵01\n似乎是希望您即刻出发，而且在出发前，\n请将兵权移交给扬州乐刺史。\n&诸葛诞\n好，我知道了。"]},{"op":"actor_move","args":[0,566,0,95,54,1]},{"op":"actor_select","args":[0,566,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"actor_face","args":[722,6,3]},{"op":"dialog","args":["&诸葛靓\n恭喜爹您升官了。\n&诸葛诞\n恭喜个屁！我快大祸临头了。\n&诸葛诞\n我当三公的顺序，不管怎么样都会在王昶\n之后，现在又只派一个小兵来传令，怎么\n想都和乐綝脱离不了关系。\n&诸葛诞\n你们说我该去，还是不该去？"]},{"op":"actor_face","args":[1,0,3]},{"op":"dialog","args":["&诸葛果\n夏侯太初的事情，似乎距离现在还不久。\n&诸葛诞\n夏侯太初？！对呀…这个该死的司马昭，\n居然完全不念我们之间的关系。"]},{"op":"actor_face","args":[131,0,3]},{"op":"dialog","args":["&蒋班\n大将军从来就没有信任过您，不然他\n就不会派贾充来探您口风了。"]},{"op":"actor_face","args":[132,0,3]},{"op":"dialog","args":["&焦彝\n当初就说过帮司马家是大错特错，现在\n灾难临头才知道了吧。\n&诸葛诞\n你们两个最近说话越来越不留余地。\n&诸葛诞\n我被司马家蒙骗了，一直以来，我以为\n司马家只是想要夺得权力来保护自己，\n从来没想过他们会有篡位的念头。\n&诸葛果\n真的没想过？\n&诸葛诞\n什么？\n&诸葛果\n当司马懿屠杀曹爽的时候，你真的没想过\n司马家的夺权行动已经变质？\n&诸葛果\n当司马师废黜皇帝的时候，你真的没想过\n他已经在觊觎皇帝位子？\n&诸葛果\n当毌丘俭起兵的时候，你真的没想过哪边\n是真正的忠臣？\n&诸葛诞\n这……\n&诸葛诞\n（虽是女子，但是分析字字在理，真不愧\n是从兄的女儿。）\n&诸葛果\n现在是做出决定的时候，是要维护名士\n风范，还是苟且偷生，决定权都在你。\n&诸葛诞\n………"]},{"op":"delay","args":[5]},{"op":"play_sound","args":[91]},{"op":"dialog","args":["&诸葛诞\n（这么多年来，我被自己的贪心给蒙蔽了\n，明明有那么多明显的事实摆在眼前，我\n就是不肯相信司马家有逆心。）\n&诸葛诞\n（是呀，我官位节节高升，还成为司马家\n的姻亲，但我却失去了一个名士该有的气\n节。）\n&诸葛诞\n（我过著行尸走肉的日子却不自知，还因\n为自己选对边站而沾沾自喜，诸葛公休啊\n…你比起你在蜀地的从兄差太多了。）\n&诸葛诞\n（就算现在为时已晚，司马家势力已经是\n庞大到难以对抗，我还是要做我该做的事\n情。）"]},{"op":"actor_action","args":[95,6]},{"op":"dialog","args":["&诸葛诞\n我已经决定了！我诸葛诞不是司马家的家\n奴，我是四聪八达的最后一人！我要成为\n正始名士最后的典范！\n&诸葛诞\n现在即刻把扬州刺史乐綝抓过来，那家伙\n随时会成为司马昭的内应。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[6]},{"op":"change_scene","args":[2,65535,65535,10,65535]},{"op":"play_music","args":[207,0]},{"op":"actor_appear","args":[57,52,55,1,0]},{"op":"actor_appear","args":[87,58,55,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["乐綝的抉择"]},{"op":"place_name","args":["扬州议事厅"]},{"op":"dialog","args":["&庞会\n诸葛诞叛军已经快要杀进来了，您难道\n不准备逃走？\n&乐綝\n你先走吧，你一个人还有机会逃出去。\n&庞会\n可是…\n&乐綝\n别在这时候还想要效法你父亲，别忘记\n你还有更重要的使命。\n&庞会\n是呀…我还没有对关羽一家人复仇。\n&乐綝\n那你还不快走！"]},{"op":"actor_action","args":[57,6]},{"op":"dialog","args":["&庞会\n请您多保重。\n&乐綝\n（这个庞会，虽然武勇和胆识都不逊于\n他父亲庞令明，但只为复仇而活，已经\n葬送掉他的人生了。）\n&乐綝\n（唉…我还去关心他呢，自己都快性命\n不保了。）"]},{"op":"delay","args":[5]},{"op":"play_music","args":[207,255]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[13]},{"op":"actor_appear","args":[86,37,54,1,0]},{"op":"actor_appear","args":[88,37,47,1,0]},{"op":"actor_appear","args":[87,43,51,3,0]},{"op":"change_scene","args":[2,65535,65535,31,65535]},{"op":"fade_out","args":[]},{"op":"title_text","args":["半个月前"]},{"op":"place_name","args":["洛阳附近"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&乐綝\n哈哈哈，我终于升到扬州刺史啦，羡慕\n我吧，忌妒我吧！\n&张虎\n哼，这种屎缺，送给我都不要。\n&乐綝\n我就知道张辽的儿子说不出什么好话，\n你坦率点敬佩我会怎样？\n&戴陵\n两位别吵了啦，想想你们也吵了几十年，\n不觉得这是了不起的孽缘？\n&乐綝\n是呀，回想起过去这家伙小时候，居然把\n我拿来当做点心的梨子偷吃掉。"]},{"op":"actor_action","args":[86,2]},{"op":"dialog","args":["&张虎\n我倒记得有人专门抢我女朋友，我把哪个\n妹，你就去把哪个。"]},{"op":"actor_action","args":[87,0]},{"op":"dialog","args":["&乐綝\n哼，你还敢说？你上次偷我头盔，我还没\n找你算帐。\n&张虎\n那是报复你上次偷用我的黄龙钩镰刀。"]},{"op":"actor_action","args":[86,0]},{"op":"actor_action","args":[87,0]},{"op":"dialog","args":["&张虎\n乐进的儿子，这个扬州刺史的职务绝对\n不好做，你该知道你不是司马家的亲信。\n&乐綝\n我又何尝不知道？司马家对淮南诸葛诞不\n放心，所以想找个不亲近诸葛诞，却又死\n了也没关系的人去那边牵制他。\n&张虎\n你既然知道，为什么还要去赴任？\n&乐綝\n我能有选择吗？现在这个时候，有谁可以\n违抗司马家的意思？\n&戴陵\n回想起过去，我们三个人还可以公然鄙视\n司马懿，现在居然连对司马家稍微吭一声\n都不行。\n&乐綝\n如果爹或是张辽还在的话，哪可能轮到\n这些人嚣张？\n&张虎\n乐綝，不要死了！等你从扬州回来，我还\n想和你好好喝一杯。\n&乐綝\n哼，我可是不死身的乐綝，你就把你的酒\n给我准备好吧。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[91]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[95,29,54,1,0]},{"op":"actor_appear","args":[131,48,41,2,0]},{"op":"actor_appear","args":[132,48,69,0,0]},{"op":"actor_appear","args":[87,48,54,3,0]},{"op":"actor_appear","args":[258,51,58,3,0]},{"op":"actor_appear","args":[259,51,52,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["乐綝的骨气"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"actor_action","args":[87,0]},{"op":"dialog","args":["&乐綝\n诸葛诞，你身受朝廷大恩，怎么敢造反，\n袭击朝廷命官？\n&诸葛诞\n这才是我要对你说的，你父亲乐进是武帝\n最信赖的将领之一，对大魏忠心耿耿。\n&诸葛诞\n怎么到你这代，变成司马家的走狗！"]},{"op":"actor_action","args":[87,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&乐綝\n诸葛诞，我只问你一次，你究竟是真心想\n要起兵匡复魏室，还是想要自保而已？\n&诸葛诞\n你这司马家的走狗，凭什么问我这个！\n&乐綝\n司马懿滥杀宗室，司马师擅行废立，\n司马昭妄想篡逆，这些事情我也知道。\n&乐綝\n可叹武帝时的名将，只要有一人在此，\n又怎么可能轮到他们在那猖狂。\n&诸葛诞\n等一下，你是支持我起兵？\n&乐綝\n如果你是真心想要起兵，我又怎么可能\n不支持，我是乐文谦的儿子，就算能力\n再差，我也有我的骨气。\n&乐綝\n但是…我没有办法抛下我的妻儿不顾，\n我的肇儿还年幼，我不希望他因为我而\n被牵连。\n&乐綝\n所以请你杀我，这样我麾下的军队都可以\n归你统率。\n&诸葛诞\n为什么你要做到这种地步？\n&乐綝\n我乐綝浑浑噩噩过了数十年，从来没有为\n大魏做任何一件事，今天只要用我的血，\n就可以拯救大魏，我何乐不为？\n&诸葛诞\n你真的不再考虑和我一起起义？"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[87,6]},{"op":"dialog","args":["&乐綝\n祝你起兵顺利，推翻司马家，让武帝建立\n的大魏回复原有的光彩。\n&乐綝\n（张虎，原谅我不能和你喝一杯了，只希\n望你能体会我的苦心，不要像我这样，到\n现在无奈只能用这种方式来报效大魏。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[91]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,32,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二五七年，朝廷下诏诸葛诞担任司空，命返洛阳就职。",1,0,1]},{"op":"delay","args":[8]},{"op":"caption","args":["诸葛诞接到诏书后，决意起兵，斩杀扬州刺史乐綝，合并其部队。",1,1,1]},{"op":"delay","args":[8]},{"op":"caption","args":["诸葛诞一口气聚集淮河南北各县的屯垦部队十余万，及扬州精兵四五万人，",0,1,1]},{"op":"delay","args":[8]},{"op":"caption","args":["，积存粮食够供应大军一年使用。\n",1,1,1]},{"op":"delay","args":[8]},{"op":"caption","args":["诸葛诞决意闭城自守，在寿春城作长期抗战的准备。",0,0,1]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[3]},{"op":"change_scene","args":[2,65535,65535,61,65535]},{"op":"actor_appear","args":[1,57,67,1,0]},{"op":"actor_appear","args":[18,52,70,1,0]},{"op":"actor_appear","args":[19,52,62,1,0]},{"op":"actor_appear","args":[722,64,67,3,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["勇气"]},{"op":"place_name","args":["寿春 诸葛府"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[722,6]},{"op":"dialog","args":["&诸葛靓\n明天我就要以人质的身分前往东吴，所以\n现在特别向各位辞行。\n&赵统\n人质？难道你们要向东吴投降？\n&诸葛靓\n应该是这样没错。\n&赵统\n这实在是太奇怪了！不是说要起兵反\n司马家吗？为什么反而要降东吴，把敌人\n引进自己的国土？\n&诸葛靓\n对不起，有件事情我一直想问外姊您，\n您身后的这两位将军是谁？"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[18,6]},{"op":"actor_action","args":[19,6]},{"op":"dialog","args":["&赵统\n忘记自我介绍，在下赵云之子赵统。\n&赵广\n同样是赵云之子，也是赵统之弟赵广。\n&诸葛靓\n原来是名满天下赵云将军的儿子，失敬\n失敬。\n&诸葛靓\n说实话，我也不知道爹到底在想什么，既\n然要起兵反正，就应该大张旗鼓向各地号\n召响应，怎么能这样投降敌人。\n&赵广\n我想应该和过去毌丘俭失败，知道指望\n各地响应是没用的关系吧。\n&赵广\n更何况，过去诸葛将军的立场反反覆覆，\n一下子帮司马师，现在又反司马昭，这样\n怎么可能有号召力？\n&诸葛果\n其实问题没有那么复杂，单纯是族叔在\n迷惘而已。\n&诸葛靓\n迷惘？因为姊姊的关系？毕竟她也是\n司马家的媳妇。\n&诸葛果\n或许是，只是要想到对抗这个权大势大的\n司马家，任谁不会感到恐惧呢？特别是之\n前还仰仗司马家权势的他。\n&诸葛果\n不过不要紧，族叔已经踏出最勇敢而且\n艰钜的一步，剩下就静观其变就好。\n&赵统\n可是…\n&诸葛果\n我们的目的是要拯救诸葛诞的内心，现在\n既然他都已经觉醒，我们又何必再多计较\n呢？\n&诸葛果\n你的父亲是伟大的，我也以这个族叔为荣\n，只要记住这点就好。\n&赵广\n（我一直以为，诸葛姑娘来这边的目的，\n是要煽动诸葛诞造反，好缓和我大汉现在\n危险的情势，难道不是这样？）\n&赵统\n（我真的不懂，如果诸葛诞这次起兵弄成\n这样的话，我们大汉哪可能再度有起兵的\n机会？）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[55]},{"op":"change_scene","args":[2,65535,65535,8,65535]},{"op":"actor_appear","args":[163,34,53,1,0]},{"op":"actor_appear","args":[127,44,41,2,0]},{"op":"actor_appear","args":[179,50,41,2,0]},{"op":"actor_appear","args":[196,56,41,2,0]},{"op":"actor_appear","args":[184,44,68,0,0]},{"op":"actor_appear","args":[180,50,68,0,0]},{"op":"actor_appear","args":[173,56,68,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["东吴发兵"]},{"op":"place_name","args":["建业大将军府"]},{"op":"dialog","args":["&孙綝\n诸葛诞把他的儿子送来当人质，还向我们\n大吴称臣。\n&孙綝\n现在如果我们得到寿春，将可以让大吴的\n领土，一口气拓展到淮南一地，这可是过\n去大皇帝所没有做到的事情。\n&孙綝\n因此，我决定亲自率军增援诸葛诞，武昌\n方面就由镇南将军朱异率军增援。"]},{"op":"delay","args":[8]},{"op":"actor_face","args":[184,6,3]},{"op":"dialog","args":["&鲁淑\n在下认为这件事情应该要从长计议才是，\n现在我大吴内部也不稳，夏口督孙壹才\n刚刚叛逃，我军军心需要时间回复。\n&孙綝\n孙壹那个小人物不值一提，曹贼居然还\n把他当宝，我看司马昭那家伙真是蠢得\n可笑。\n&孙綝\n（虽然从兄为了保卫孙家人才传位予我，\n但我还是要排挤可能威胁我的宗室近亲，\n才能确保我这疏属的权位。）\n&鲁淑\n不，那是可怕的政治号召作战，想想连\n个孙壹都可以获得礼遇，更何况是其他\n高官？"]},{"op":"actor_action","args":[163,2]},{"op":"dialog","args":["&孙綝\n住口！要是有人敢效法孙壹，我就会让他\n死得比孙宪或是王惇还惨！\n&鲁淑\n（大将军现在已经是杀红了眼，为了他的\n权力，杀掉吕据和滕胤不说，甚至连孙峻\n时代得宠的孙宪都杀。）\n&鲁淑\n………\n&孙綝\n（若不是他是鲁子敬的儿子，我早就把\n他宰了。幸好他识相，不再说下去。）\n&孙綝\n我想镇北大将军应该很熟悉寿春的情况，\n我希望你能带领三万军队，先行去支援\n寿春。"]},{"op":"actor_action","args":[163,0]},{"op":"delay","args":[8]},{"op":"actor_face","args":[127,6,3]},{"op":"dialog","args":["&文钦\n等一下，大将军不知道我和诸葛诞的关系\n非常恶劣？\n&孙綝\n大敌当前，我认为你们应该可以和睦相处\n才是，难道你会为了私怨而不顾大局？\n&文钦\n不，您说的是，我愿意率军先行援救\n诸葛诞。\n&文钦\n（忍耐，为了昭伯和仲恭的理想，我一定\n要忍耐。）\n&孙綝\n那么唐咨、于诠和全怿等人，也跟随去\n援救寿春。"]},{"op":"actor_face","args":[196,0,3]},{"op":"dialog","args":["&全怿\n等一下，我也要去？\n&孙綝\n废话！你以为你姓全就有特权？我和从兄\n不同，不管是谁，都会一视同仁对待！\n&全怿\n（我苦啊，似乎这个大将军一开始就对\n我们全家有意见，娘说的话对他也没有\n任何用处，我们全家早晚要倒楣了。）\n&孙綝\n（哼，我才不像族兄，胃口好到连那种\n年纪的阿婆都吃得下去，全家那群废物\n，既无用又占满高位，早晚干掉他们。）"]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[55]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,34,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二五七年，东吴在诸葛靓作为人质，到达东吴以后，",1,0,1]},{"op":"delay","args":[8]},{"op":"caption","args":["，皇帝孙亮即刻任命诸葛诞为大司徒、骠骑将军和青州刺史。",1,1,1]},{"op":"delay","args":[8]},{"op":"caption","args":["大将军孙綝派遣镇北大将军文钦，率领三万人先行出发，援救寿春（淮南）。",0,0,1]},{"op":"delay","args":[8]},{"op":"caption","args":["孙綝本人也率领大军挺进，并指挥武昌的朱异和丁奉等人朝向寿春出发。",1,1,1]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[71]},{"op":"change_scene","args":[2,65535,65535,11,65535]},{"op":"actor_appear","args":[130,49,71,0,0]},{"op":"actor_appear","args":[199,36,55,1,0]},{"op":"actor_appear","args":[100,36,50,1,0]},{"op":"actor_appear","args":[102,36,45,1,0]},{"op":"actor_appear","args":[103,63,55,3,0]},{"op":"actor_appear","args":[106,63,50,3,0]},{"op":"actor_appear","args":[107,63,45,3,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["出兵平乱"]},{"op":"place_name","args":["洛阳大将军府"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&司马昭\n诸葛诞果然造反了，我在计画上稍微加点\n料，引诱他杀了乐綝，这下他再也无法回\n头了。\n&司马昭\n不过他真是差毌丘俭一大截，仗都没打就\n投降东吴，还敢说自己是忠臣义士？\n&司马昭\n我将率领大军，亲自平定诸葛诞乱事，\n并且顺道让吴贼再也无进军淮南的实力。\n&司马昭\n让镇南将军王基代镇东将军，都督扬豫州\n诸军事。\n&司马昭\n安东将军陈骞和豫州刺史州泰会同王基\n平乱。\n&司马昭\n荆州刺史鲁芝和青州都督石苞也同时率军\n支援，这样动员人数应该可超过二十万。"]},{"op":"actor_face","args":[100,6,2]},{"op":"dialog","args":["&贾充\n王基和鲁芝可以信赖吗？他们曾经担任\n过曹爽的部属…\n&司马昭\n公闾呀…上次能够平定毌丘俭叛变，如果\n没有伯舆的力量，根本不可能办到。\n&司马昭\n我信任他们，就如同信任公闾你一样，\n请不要再怀疑他们的忠诚了。"]},{"op":"actor_face","args":[107,6,2]},{"op":"dialog","args":["&钟会\n大将军…\n&司马昭\n士季呀，虽说这次激反诸葛诞为我所愿，\n但你说的也不无道理。\n&司马昭\n其实诸葛诞年事已高，只要等他死亡即可\n，不需要去激反他制造国家的危难。\n&司马昭\n要是早点接到你的信，或许我不会派公闾\n去见诸葛诞。\n&钟会\n过去的事情就算了，现在应该是想办法\n尽快平乱才是。\n&司马昭\n关于令堂的丧事，已经办好了？\n&钟会\n没问题了，比起对母亲的小孝，我想要\n对大将军尽大孝，相信母亲的在天之灵\n也能理解我的作为。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&钟会\n这次大将军准备得非常周到，但是您似乎\n忘记做一件事了。\n&钟会\n您打算亲自征讨诸葛诞，无疑是最正确的\n选择，然而上次的教训不可忘。\n&司马昭\n上次的教训…哎呀，我还真差点忘记了。\n&司马昭\n这就请求圣上和太后一起随同出征，另外\n，也把东乡公主给我一并带上。\n&钟会\n（从他少见的慌张神情看来，似乎当时\n那件事情，对大将军还是梦魇一场。）\n&司马昭\n士季，做得好！你真是我的张子房啊。\n&荀顗\n（那不是当初武帝夸赞我老爹的话？\n大将军说这话，可把他的野心表露得\n一览无遗呀。）\n&裴秀\n（这个钟会，他什么时候这么得到大将军\n的信任了…明明是我比较早跟随大将军，\n现在却完全落后了。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[56]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[69,51,29,1,0]},{"op":"actor_appear","args":[24,56,29,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["忍辱负重"]},{"op":"place_name","args":["洛阳宫殿"]},{"op":"dialog","args":["&曹髦\n姑姑，司马昭实在是太过分了！居然要把\n朕、太后和您带著去征讨诸葛诞！\n&曹髦\n朕很清楚诸葛诞起兵是为了推翻司马家，\n然而朕却得窝囊地帮著打对朕忠心的人，\n这实在是难以忍受！\n&曹绫\n司马昭记取了上次的教训，所以有这样的\n行动，我并不意外。\n&曹绫\n诸葛诞一开始就退缩，闭城自守又投降\n东吴，已经失掉先机，司马昭此举还有\n压抑住其他亲魏室将领的效果。\n&曹髦\n可恶！难道就任他摆布？\n&曹绫\n现阶段来说，我也只能这样说，我们只能\n乖乖听他的话。\n&曹绫\n我不是说过，一定要忍，因为你有著远远\n超过司马昭的年轻活力。\n&曹髦\n可是，每次想到武皇帝的武功，朕就觉得\n朕实在是没用到家。\n&曹绫\n你错了，自从昭伯和他的势力覆亡之后，\n我们和司马家的实力就完全逆转过来。\n&曹绫\n纵然是祖父复生，恐怕也很难击倒\n司马家。\n&曹绫\n你也不要妄自菲薄，现在毕竟是形势比\n人强，我们能做的，就只有忍耐而已。\n&曹髦\n是…\n&曹髦\n（姑姑，我虽然很尊敬您，但是只有这点\n我不同意。我认为如果是武皇帝，一定会\n拔刀和司马家一搏，这才是英雄作为。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["公元二五七年，六月二十五日，曹魏皇帝\n曹髦和太后一行人抵达项县，司马昭则统\n率各路大军二十六万，进抵丘头。\n\n然而司马昭布置的包围网还没有完成，东\n吴的援军，文钦等人已经抵达，从寿春城\n东北，沿八公山挺进，全体入城。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[91]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[95,29,54,1,0]},{"op":"actor_appear","args":[131,48,41,2,0]},{"op":"actor_appear","args":[132,56,41,2,0]},{"op":"actor_appear","args":[127,48,54,3,0]},{"op":"actor_appear","args":[128,53,57,3,0]},{"op":"actor_appear","args":[129,53,51,3,0]},{"op":"actor_appear","args":[179,59,57,3,0]},{"op":"actor_appear","args":[196,59,51,3,0]},{"op":"actor_appear","args":[180,65,57,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["吴越同舟"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"dialog","args":["&诸葛诞\n………\n&文钦\n………\n&唐咨\n怎么气氛那么僵？\n&蒋班\n（东吴这帮傻鸟似乎还不知道这两人之前\n结怨有多深吧。）\n&诸葛诞\n想不到孙大将军会派出这么强力的援军，\n我是该感激他吗？"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[127,6]},{"op":"dialog","args":["&文钦\n文钦奉命来协助防守寿春城，一切谨遵\n诸葛将军指示。\n&诸葛诞\n仲若，想不到我们会有携手合作的一天。\n&文钦\n如果我们早点携手合作的话，现在我们\n应该在洛阳，和仲恭一起辅佐圣上。\n&焦彝\n（哇勒，这两个人是想要当场干起来？）\n&文钦\n不过…因为你的起义，让我有机会重新\n回到这熟悉的土地上，贯彻对抗司马家\n的大义。\n&文钦\n关于这点，我还是很感激你。\n&诸葛诞\n（这个莽夫居然变得这么会说话，要是\n早点这样，我也不至会这么讨厌他。）\n&文钦\n（为了再次高揭大魏的大义，为了成就\n毌丘仲恭未完成的志业。寿春城啊，\n我回来了！）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[5]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[114,34,54,1,0]},{"op":"actor_appear","args":[113,48,43,2,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["王基的坚持"]},{"op":"place_name","args":["寿春 魏军营帐"]},{"op":"actor_face","args":[113,6,3]},{"op":"dialog","args":["&陈骞\n现在大将军的主力部队没有到，我们如果\n和敌人硬碰硬，应该是没有赢的机会。\n&陈骞\n（你想死我才不管你，我可是要留著命去\n嫖妓的。）\n&王基\n休渊，你的想法非常正确，但还是有修正\n的空间。\n&王基\n先不说城内十几万的部队，城外在附近\n游击的朱异部队，才是我们真正该烦恼\n的对象。\n&陈骞\n是呀，那个朱异也知道不要和我们正面\n对决，只是停留在外围，和城内军队相\n呼应而已。\n&王基\n大将军虽然命我们坚守，但是如果不先\n解决掉朱异的军队，要固守几乎是不可能\n的任务。"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[571,97,56,3,0]},{"op":"actor_move","args":[0,571,0,48,56,3]},{"op":"actor_action","args":[571,6]},{"op":"delay","args":[5]},{"op":"dialog","args":["&使者\n启禀镇南将军，圣上下诏要您进据\n八公山。\n&王基\n现在我军包围网已经完成，营垒坚固，只\n要加强防御工事，严密提防他们逃走就行\n了。\n&王基\n如果转移阵地，使贼寇逃出城外，以后就\n是再有本事的人，恐怕也难以收拾残局。\n&使者\n可圣上的命令…"]},{"op":"actor_action","args":[114,6]},{"op":"dialog","args":["&王基\n我拒绝执行这样的命令，就这样对圣上\n说吧。\n&王基\n和贼寇对峙，应该像大山一样，毫不动摇\n。如果迁到险要之处，军心动荡，声势就\n已经居下风。\n&王基\n现在各军都已经进入深沟高垒之中，人心\n笃定，不应该使他们受到搅扰，这是作战\n的要领。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["王基的奏章，不久之后被批准。王基开始\n加强对寿春的包围网，里外数重，壕沟深\n陷，营垒坚固。\n\n文钦等人数次尝试突围，都遭到王基迎头\n痛击，被驱赶回城里面。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[71]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[130,34,54,1,0]},{"op":"actor_appear","args":[114,48,43,2,0]},{"op":"actor_appear","args":[113,53,43,2,0]},{"op":"actor_appear","args":[103,58,43,2,0]},{"op":"actor_appear","args":[663,63,43,2,0]},{"op":"actor_appear","args":[801,68,43,2,0]},{"op":"actor_appear","args":[86,73,43,2,0]},{"op":"actor_appear","args":[112,48,69,0,0]},{"op":"actor_appear","args":[107,53,69,0,0]},{"op":"actor_appear","args":[133,58,69,0,0]},{"op":"actor_appear","args":[134,63,69,0,0]},{"op":"actor_appear","args":[119,68,69,0,0]},{"op":"actor_appear","args":[147,73,69,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["破敌方案"]},{"op":"place_name","args":["寿春 魏军营帐"]},{"op":"dialog","args":["&司马昭\n伯舆，若不是你的择善固执，恐怕现在\n寿春防线就被敌人突破了。"]},{"op":"actor_face","args":[114,6,3]},{"op":"dialog","args":["&王基\n现在敌人已经被彻底赶回城内，短时间内\n不可能再出击。\n&王基\n我认为应该趁著敌人士气受挫的机会，\n一口气攻陷寿春城！"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[133,6,3]},{"op":"dialog","args":["&石苞\n我也认为应该发动攻势，这样就可以解救\n寿春的妇女同胞！\n&司马昭\n咳…我们是奉旨讨贼，你难道又在动什么\n歪脑筋？\n&石苞\n没什么啦，我最近身体虚弱，需要十个\n八个女人陪睡。\n&司马昭\n（这个石仲容虽然长得好看，头脑又聪明\n，但是个性轻浮又好色成性，难怪爹当年\n不肯重用他。）\n&司马昭\n（大哥只是想他虽然人品差，但也有些\n经国才略，就姑且一用，只是这人真的\n值得我们司马家败坏名声也要用？）\n&司马昭\n寿春城坚固，而且守军众多，攻城一定会\n受到挫折，如果外援再来，正好腹背受敌\n，是危险的策略。\n&司马昭\n而今，文钦、诸葛诞和唐咨这三个叛徒聚\n集在一个孤城中，这是上天要他们一起被\n诛杀。\n&司马昭\n我们应该紧密包围三面，如果吴贼从陆地\n赴援，粮食携带不便，数量也有限，我们\n用轻装骑兵切断粮道，不战即可退敌。\n&司马昭\n只要能击破吴贼援军，城内的贼寇必定会\n束手就擒。\n&王基\n话虽如此，但城外朱异的游击部队该怎么\n处理？如果不收拾掉他，我们很难专心进\n行包围行动。"]},{"op":"actor_face","args":[86,2,3]},{"op":"dialog","args":["&张虎\n让我去！我要杀光吴贼和诸葛诞一干人\n等！\n&司马昭\n不行！你身为名将之后，也该知道光凭\n血气之勇，无法破敌。\n&张虎\n（我恨呀，司马家根本不信任我，可我为\n了帮乐綝你报仇，却又不得不委身在他们\n底下。）\n&鲁芝\n（没想到这次居然得率军帮司马家作战，\n在座的不知道有多少人是过去曹大将军的\n部属，现在看来真是讽刺。）\n&鲁芝\n（不过他对我们也不完全放心，不然就\n不会当场诛杀常林的儿子给我们看。）\n&鲁芝\n（想起当初司马懿对常林再三敬拜，\n司马昭却把他儿子像杀猪一样杀掉，\n他杀我们更不会犹豫。）\n&司马昭\n朱异怎么说也是吴贼顶尖名将之一，可能\n得劳驾伯舆你了。"]},{"op":"actor_face","args":[86,0,3]},{"op":"play_sound","args":[56]},{"op":"actor_appear","args":[24,97,56,3,0]},{"op":"actor_move","args":[0,24,0,48,56,3]},{"op":"actor_action","args":[24,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n大将军，对付那样的部队，你不需要派出\n我军的王牌。\n&胡奋\n这不是公主吗？怎么会出现在这个地方？\n&司马昭\n是我要她来的，她的文韬武略和爹可说是\n不相上下，对于破贼一定会有所帮助。\n&司马昭\n（放著你待在圣上身边才更危险，只有把\n你紧紧扣在我身边，我才可以放心。）\n&陈泰\n（现在的我和公主的立场没有任何差别，\n都是因为不信任被紧紧扣在身边呀。）\n&陈泰\n（子上，我知道你想要给我机会，希望我\n能表现出恭顺的态度。但是很可惜，我做\n不到。）\n&曹绫\n我认为，奋武将军石苞有勇有谋，足够\n对付朱异。\n&胡烈\n太夸张了吧，那个好色鬼能够做什么？\n&司马昭\n不，记得东关大败的时候，只有仲容的\n军队能够全身而退，或许他真的有才能。\n&司马昭\n（能屈能伸？也对，虽说我不能明目张胆\n杀她，但是直接囚禁她也不难…她应该是\n用具体行动表示自己和叛军无关吧。）\n&司马昭\n仲容！你带著州泰和胡烈等人去迎击朱异\n，我会把帐下最精锐的部队交给你。\n&石苞\n是的！我一定会战胜朱异！\n&石苞\n（呵呵，东吴听说女将多，趁机带两个来\n治疗我的性饥渴。）"]},{"op":"actor_face","args":[134,0,3]},{"op":"dialog","args":["&州泰\n石将军！你最好收敛点！我平常劝谏你的\n话可从来没有少过。\n&石苞\n（这州泰正经八百的，真是讨人厌，我就\n不相信摆两个大奶妹在身边你不要。）\n&石苞\n（不过说真的，眼前这个公主真是正翻了\n，打赢的话，可以请她亲自慰劳我？）\n&胡烈\n（瞧他这副色咪咪的样子，真的能够打仗\n？真羡慕大哥可以待在大将军身边。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["石苞率领的分队，完全不辜负司马昭的期\n望，由州泰在阳渊给予朱异部队迎头痛击\n，州泰继续追击，杀伤两千余人。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[6]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[133,34,54,1,0]},{"op":"actor_appear","args":[134,48,43,2,0]},{"op":"actor_appear","args":[147,48,69,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["石苞之才"]},{"op":"place_name","args":["寿春 魏军游击军营帐"]},{"op":"dialog","args":["&石苞\n怎么？！你们两个人看我，怎么还有怀疑\n的眼神？仗不是都打赢了？\n&胡烈\n走运。\n&州泰\n实际出兵的可是我，石将军你唯一做的\n事情，是在后面捡吴贼败军的物资。\n&石苞\n啊…就…济贫嘛。"]},{"op":"actor_face","args":[134,0,3]},{"op":"dialog","args":["&州泰\n喂，现在贼首孙綝亲自率军来到，朱异\n这次获得完全的补给，实力可不同凡响。\n&州泰\n偏偏你却无动于衷，只知道在这边吃喝\n玩乐，想找死，不要拖著我一起下水！\n&石苞\n你一定是觉得我这个人人品低劣，只是\n靠著运气升到今天的高位。\n&州泰\n我可没这样想。\n&石苞\n你有没有想过为什么过去太傅赏识你，\n轻蔑我，到最后我却爬得比你高的原因？\n&石苞\n比道德，你我这种平民出身的，怎么样也\n比不过儒学世家子弟，这点我想曾经被那\n钟会羞辱过的你也该很清楚。\n&石苞\n所以不如放纵自己，反正我是没水准的\n死老百姓，贪财好色都是应该的。\n&石苞\n而正因为我好色又贪吝，只是个胸无大志\n的废物，所以不更让人放心？\n&州泰\n（等一下…莫非他是效法王翦？）\n&石苞\n嘿嘿嘿…听说东吴专出正妹，到时候要是\n抓到朱异，逼他们用十个美女和我交换俘\n虏。\n&州泰\n（我多心了，他根本骨子里就是个\n大淫棍。）"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[147,6,3]},{"op":"dialog","args":["&胡烈\n我认为应该率军去突袭吴贼的粮草所在，\n只要切断他们粮草供应，要打败一群饿坏\n了的兵士，并不困难。\n&石苞\n好是好，但你知道粮草的位置？\n&胡烈\n总会找得到…\n&石苞\n真是的…就在都陆一带。\n&胡烈\n咦？\n&石苞\n你真当我坐在这边什么都不做？从上次\n交手就知道那家伙无心作战，只是稍微\n晃一下就回去，所以把粮草放在后方。\n&石苞\n不过这次，我要让他的安排，变成毁灭\n他部队的致命伤。\n&石苞\n命你率领五千精兵，袭击都陆，摧毁朱异\n的粮草供应。\n&胡烈\n是！\n&石苞\n还有…\n&石苞\n如果发现什么宝贝，记得要带回来，\n我要济贫。\n&胡烈\n……"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[6]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,0,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["孙綝再命朱异率领丁奉等人，前去援救寿春。",1,0,1]},{"op":"delay","args":[8]},{"op":"caption","args":["朱异把辎重粮秣，留在都陆，自己率军挺进到黎浆。石苞再度迎击，击破朱异。",1,1,1]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"delay","args":[8]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,14,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["朱异残兵陷入饥饿状态，沿途吃树叶充饥，勉强回到孙綝大营。",0,0,1]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[70]},{"op":"change_scene","args":[2,65535,65535,21,65535]},{"op":"actor_appear","args":[163,48,67,0,0]},{"op":"actor_appear","args":[181,48,54,2,0]},{"op":"actor_appear","args":[166,61,54,3,0]},{"op":"actor_appear","args":[165,61,49,3,0]},{"op":"actor_appear","args":[220,61,44,3,0]},{"op":"actor_appear","args":[168,36,54,1,0]},{"op":"actor_appear","args":[173,36,49,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["朱异殉难"]},{"op":"place_name","args":["吴军营帐"]},{"op":"actor_action","args":[163,2]},{"op":"dialog","args":["&孙綝\n搞什么东西，你们吴郡朱家部曲不是号称\n所向无敌，怎么打成这副德行？"]},{"op":"actor_action","args":[181,2]},{"op":"dialog","args":["&朱异\n这场战争根本就是大错！人家魏贼家里面\n的事情，为什么要牵连到我们？\n&孙綝\n难道你想放弃寿春？这可是拿下寿春的\n大好机会。\n&朱异\n别开玩笑了，寿春距离魏贼京城近，地势\n又是一片平坦，适合骑兵行进，我军以步\n军和水军为主，根本无法守住那里。\n&孙綝\n你是在质疑我的方针？\n&朱异\n我不希望朱家子弟在这样的战场上牺牲。\n&陆抗\n（这些话，真是说到我心坎里了。这场战\n争，对我江东大族根本毫无意义，守也守\n不住，得到的人力也有限。）\n&孙綝\n现在就率领你的部队，给我好好打一仗！\n&朱异\n我拒绝！我的部队才刚从饥饿状态中\n逃出来，根本就没有战斗力。\n&孙綝\n我再说最后一次，给我出战！\n&朱异\n我拒绝！既然你口口声声说要拿下寿春，\n为什么你的军队却从来没有动一下。\n&孙綝\n我有我的考量。\n&孙綝\n（这场战争，我本来就只打算让朱异的部\n队去打，我才不会像诸葛恪那么笨，把自\n己手上的筹码都败光。）\n&孙綝\n（现在我离开建业也有一段时间，全家班\n的人在背后给我搞鬼的话，事情就变得很\n麻烦，看来是要赶快回军建业为上策。）\n&丁奉\n季文！不要这样固执！就听大将军的话\n吧。\n&朱异\n过去大皇帝也从没有这样命令过父亲，\n你凭什么这样命令我吴郡朱家！\n&孙綝\n吴郡朱家？笑死人了，我谁没杀过，怕你\n小小的吴郡朱家？"]},{"op":"actor_action","args":[163,0]},{"op":"actor_action","args":[181,0]},{"op":"actor_face","args":[166,6,2]},{"op":"dialog","args":["&丁奉\n不可呀，再怎么说，吴郡朱家都是我大吴\n的支柱。\n&孙綝\n放屁！我就不相信，这个吴郡朱家能有\n多大本事！\n&丁奉\n大将军，拜托您三思呀。"]},{"op":"actor_action","args":[163,17]},{"op":"dialog","args":["&孙綝\n来人！"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[567,47,22,2,0]},{"op":"actor_appear","args":[568,51,22,2,0]},{"op":"delay","args":[5]},{"op":"actor_move","args":[0,567,0,45,54,2]},{"op":"actor_move","args":[0,568,0,51,54,2]},{"op":"actor_action","args":[567,0]},{"op":"actor_action","args":[568,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&孙綝\n把这个违抗军令的逆贼给我拖下去砍了！\n&丁奉\n大将军，季文是威镇国际的名将，斩他\n将会对我大吴造成难以弥补的损失。\n&孙綝\n笑话，我就不相信一个小小朱异能有\n多了不起。\n&丁封\n镇南将军，您也向大将军道歉认错吧。"]},{"op":"actor_action","args":[181,2]},{"op":"dialog","args":["&朱异\n我没有错，为什么要认！\n&孙綝\n快！给我砍了他！\n&士兵02\n是！\n&朱异\n孙綝，你这个无能又残暴的蠢猪，我在\n那边等著看你被诛杀的一天。"]},{"op":"actor_move","args":[0,181,0,50,21,0]},{"op":"actor_move","args":[0,567,0,46,21,0]},{"op":"actor_move","args":[0,568,0,54,21,0]},{"op":"actor_select","args":[0,181,0,0,0,0,6]},{"op":"actor_select","args":[0,567,0,0,0,0,6]},{"op":"actor_select","args":[0,568,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[20]},{"op":"play_music","args":[35,1]},{"op":"delay","args":[20]},{"op":"dialog","args":["&陆抗\n（我本来以为孙綝这家伙不管再怎么残忍\n，终究只会杀北方人或是孙家亲族。）\n&陆抗\n（过去孙峻看我们江东士族已经退居二线\n，因为没有威胁性，所以从来没有杀过任\n何一人。）\n&陆抗\n（然而这次居然把吴四姓中，最具有代表\n的朱家当家给杀了，这就表示他的屠刀\n也将对向我们，我们不能再冷眼旁观。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[70]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,16,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["东吴镇南将军朱异，以部下饥饿，没有战斗力为由，拒绝孙綝的出兵命令。\n",1,0,1]},{"op":"delay","args":[8]},{"op":"caption","args":["没想到，孙綝居然当场斩杀朱异。",1,1,0]},{"op":"delay","args":[8]},{"op":"caption","args":["不久后，孙綝率领大军返回建业。",0,0,1]},{"op":"delay","args":[8]},{"op":"caption","args":["因为他既不能救出诸葛诞，又丧师辱国，诛杀名将，全国上下，开始怨恨孙綝。",1,1,1]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[71]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[130,34,54,1,0]},{"op":"actor_appear","args":[24,48,43,2,0]},{"op":"actor_appear","args":[114,53,43,2,0]},{"op":"actor_appear","args":[113,58,43,2,0]},{"op":"actor_appear","args":[103,63,43,2,0]},{"op":"actor_appear","args":[86,68,43,2,0]},{"op":"actor_appear","args":[663,73,43,2,0]},{"op":"actor_appear","args":[147,78,43,2,0]},{"op":"actor_appear","args":[112,48,69,0,0]},{"op":"actor_appear","args":[107,53,69,0,0]},{"op":"actor_appear","args":[133,58,69,0,0]},{"op":"actor_appear","args":[134,63,69,0,0]},{"op":"actor_appear","args":[801,68,69,0,0]},{"op":"actor_appear","args":[119,73,69,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["胜败的分歧"]},{"op":"place_name","args":["寿春 魏军营帐"]},{"op":"dialog","args":["&司马昭\n好好好，仲容的表现真令我大开眼界，\n能以少数精兵打败吴贼的精锐部队。\n&司马昭\n这次你辛苦了，你想要什么赏赐？"]},{"op":"actor_face","args":[133,6,3]},{"op":"dialog","args":["&石苞\n十个美女就够！\n&州泰\n你…你怎么这么丢人！还说得这么理直\n气壮！\n&陈骞\n哼，没出息。\n&州泰\n你看！被人家鄙视了吧。"]},{"op":"actor_face","args":[133,0,0]},{"op":"dialog","args":["&石苞\n哼，你们这些伪君子，我就不相信你们\n不想要美女。\n&陈骞\n（如果是我，我想要二十个。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&司马昭\n朱异不能挺进到寿春，孙綝把他杀掉，\n其实这并不是朱异的过错。\n&司马昭\n其实这是孙綝为了要向寿春表示歉意，\n坚定诸葛诞意志，使他希望不至于破灭。\n&司马昭\n我们现在更要加强包围网，防备他们突围\n，要用谋略，来使他们做出错误决定。"]},{"op":"actor_face","args":[107,6,3]},{"op":"dialog","args":["&钟会\n我建议散布谣言，来消耗敌人的粮食。\n&钟会\n就说东吴援军即将抵达，围城大军粮秣\n不继，已经把部分军队送到淮河以北的\n郡县，马上就要解围。\n&司马昭\n公主，你看如何？"]},{"op":"actor_face","args":[103,6,3]},{"op":"dialog","args":["&裴秀\n我以为这样的谣言起不了任何作用，难道\n贼人不会去查明真伪？\n&钟会\n（这个裴秀真碍眼，你是卯足劲要和我\n斗下去？）\n&裴秀\n（钟会，像你这样的恶人不配为司马公\n效命。）"]},{"op":"actor_face","args":[24,6,3]},{"op":"dialog","args":["&曹绫\n我想，诸葛诞应该会相信这样的谣言，对\n于城中的粮食消耗不加以控管，不出半个\n月，寿春城一定缺粮。\n&司马昭\n哦？但万一敌人因此集中兵力想要突围，\n我军又该怎么办？\n&曹绫\n敌人现在不可能突围的，因为现在城中\n人多口杂，在号令不统一的情况下，没有\n人能够统整兵力来突围。\n&司马昭\n我倒是认为，敌人或许还在等我军后方\n有发生变故喔…\n&曹绫\n现在我大魏还能发生什么样的变故？\n&司马昭\n是呀，毕竟可能制造变故的人，现在都\n已经坐在我营帐中了。\n&陈泰\n………\n&曹绫\n………"]},{"op":"delay","args":[5]},{"op":"choice","args":["缓缓围城\n发动最猛烈攻击",130]},{"op":"if","cond":"always","args":[],"end":42},{"op":"if","cond":"test_choice","args":[1],"end":37},{"op":"dialog","args":["&司马昭\n我们就慢慢围著寿春，等他们粮尽力殆\n的时候再来收拾他们。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[2],"end":41},{"op":"dialog","args":["&司马昭\n全军准备对寿春城发动最猛烈的攻击，\n务求将诸葛诞、文钦和吴贼歼灭于寿春。"]},{"op":"set_flag","args":[1026,1]},{"op":"endif","args":[]},{"op":"endif","args":[]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[31]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[95,29,54,1,0]},{"op":"actor_appear","args":[131,48,41,2,0]},{"op":"actor_appear","args":[132,56,41,2,0]},{"op":"actor_appear","args":[127,46,68,0,0]},{"op":"actor_appear","args":[179,56,68,0,0]},{"op":"actor_appear","args":[196,71,68,0,0]},{"op":"actor_appear","args":[180,78,68,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["争论"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"dialog","args":["&诸葛诞\n居然中了司马昭的诡计，这下本来应该\n充沛的粮食，现在居然开始短缺了。"]},{"op":"actor_face","args":[127,0,3]},{"op":"dialog","args":["&文钦\n早就说过要你注意粮食的消耗，偏偏你就\n是不听。\n&诸葛诞\n现在说这些有什么用，应该想想接下来的\n对策。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&文钦\n现在敌人大军正在外面筑防御工事要包围\n我们，我建议应该立刻趁工事未完成前发\n动攻击。\n&文钦\n否则包围之势形成，外面的援军也很难再\n进入了。\n&诸葛诞\n哈哈哈，仲若呀，毕竟你待在淮南的时间\n没有我久，不知道淮南这里的气候。\n&诸葛诞\n寿春每年都会下大雨，淮河会暴涨淹没\n城邑。\n&诸葛诞\n司马昭不知道这点，把部队集结在随时会\n氾滥的地方，不用我们出手，他们马上就\n会变成虾兵蟹将了。\n&诸葛诞\n到时候会合城外东吴军队，何愁大事\n不成？"]},{"op":"actor_face","args":[131,0,3]},{"op":"actor_face","args":[132,0,3]},{"op":"dialog","args":["&蒋班\n我认为朱异大军不能前进，孙綝诛杀他而\n回军。虽然嘴巴说将集结大军，实际上早\n就无能为力，只是眼巴巴看我们战败。\n&焦彝\n现在我军士气还算旺，军心也坚定，应该\n抓住机会攻击敌人单一据点，虽然不能大\n获全胜，但总会有人突围而出。\n&焦彝\n呆坐在这边等死，没有任何意义。\n&文钦\n我反对！\n&文钦\n你率领十几万大军，归附大吴。我和全怿\n等都陪你陷在必死之地，父母子女也都在\n江表。\n&文钦\n今天纵然孙綝不打算援救，圣上和全怿等\n将士的亲戚又岂能接受？\n&诸葛诞\n（说得也是，现在城中的全家班，都是东\n吴最有权势的一群人，我想就算孙綝不理\n我们，全公主也不会坐视不管。）\n&文钦\n何况中原没有一年不发生巨变，军民辛劳\n疲惫。我们再守一年，他们内部形势必定\n会发生变化，为什么要去冒这个险呢？\n&文钦\n（想当初我没有听尹大目的话，错失了反\n攻的良机，这次怎么能够重蹈上次的覆辙\n呢？）\n&蒋班\n那是馊主意啊！\n&焦彝\n如果现在不突围，等到以后我军没有战力\n时再突围，就来不及了。\n&蒋班\n不然…您可以把诸葛姑娘请来，问问她的\n意见如何？"]},{"op":"actor_action","args":[95,0]},{"op":"dialog","args":["&诸葛诞\n够了！这种事情又不是她可以决定的，\n你们再啰唆，我保证你们人头落地。\n&蒋班\n这……\n&焦彝\n（别再说了，你看看诸葛将军的眼神，那\n可是真的带有杀意的眼神。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["诸葛诞对于蒋班和焦彝的坚持己见感到愤\n怒和猜忌，打算诛杀两人。蒋班和焦彝感\n到恐惧，翻墙出城，投奔曹魏围城军。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[57]},{"op":"change_scene","args":[2,65535,65535,61,65535]},{"op":"actor_appear","args":[1,57,67,1,0]},{"op":"actor_appear","args":[95,64,67,3,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["名士诸葛诞"]},{"op":"place_name","args":["寿春 诸葛府"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[95,6]},{"op":"dialog","args":["&诸葛诞\n有件事情可以请教一下吗？"]},{"op":"actor_action","args":[95,0]},{"op":"dialog","args":["&诸葛果\n什么事情？\n&诸葛诞\n你这次前来的真正目的。\n&诸葛诞\n听说蜀地大将军姜维在上邽附近受挫，\n损失幅度不小，兵力衰弱到连防御我\n大魏的入侵都有问题。\n&诸葛诞\n我左思右想你特地从蜀地前来的原因，\n就是说动我起兵，让蜀地有喘息的时间。"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[1,6]},{"op":"dialog","args":["&诸葛果\n族叔说的完全正确。\n&诸葛果\n果在主公最需要我的时候病倒，导致主公\n面对邓艾的时候孤立无援，因此我必须要\n为主公做些什么。"]},{"op":"actor_action","args":[1,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&诸葛诞\n果然如此，我真是太小看你，同样也太小\n看族兄那支诸葛分家的厉害。\n&诸葛果\n不过族叔怎么想？如果感觉是被果骗，\n那么就请即刻诛杀我。\n&诸葛诞\n呵呵，我被骗了十多年，难得有人肯对我\n说真话，我又怎么可能杀说真话的人。\n&诸葛诞\n更何况，如果没有你推我一把，我怎么\n可能回想起自己是正始名士的事情。\n&诸葛诞\n只是，不瞒你说…想起要和我一手让它\n壮大的司马家为敌，我可是害怕得不得\n了。\n&诸葛诞\n我没毌丘仲恭的勇气，完全没有胆量和\n司马昭麾下的精兵悍将对决，只敢躲在\n寿春城抵抗。\n&诸葛果\n毌丘俭是毌丘俭，你是你，既然你能下定\n决心对抗司马家，就已经是难能可贵了。\n&诸葛诞\n我实在是很难想像后世会怎么评价我？\n是大魏的忠臣？还是愚蠢的叛贼？\n&诸葛诞\n只是可怜我的家人，恐怕都要跟著陪葬。\n或许以后，琅邪诸葛家就只剩你们蜀地\n的这支了。\n&诸葛果\n不，你忘记你的女婿是司马家的人？还有\n因为毌丘俭叛乱后修改的法律？\n&诸葛诞\n你真的是怪物，怎么会连我大魏的事情都\n知道得这么清楚。\n&诸葛诞\n说得也是，小女很可能会因为嫁给司马槺\n而逃过一劫，而且司马家还有混著我诸葛\n家的血统…哼，哈哈哈哈哈…\n&诸葛诞\n看来这场仗，我不管怎么样都会是赢家…\n&诸葛果\n就让果陪你到最后吧。\n&诸葛诞\n我怎么能害你跟我一起死？想办法活下去\n，以你的聪明才智，一定可以找到活路。\n&诸葛诞\n（这个诸葛果对我坦白，应该可以信任，\n但是其他人呢？文钦可以信任？东吴将领\n可以信任？）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[95]},{"op":"change_scene","args":[2,65535,65535,23,65535]},{"op":"actor_appear","args":[165,50,62,0,0]},{"op":"actor_appear","args":[220,50,55,2,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["奇兵的行动"]},{"op":"place_name","args":["寿春附近"]},{"op":"dialog","args":["&陆抗\n再往前走就是贼营的包围网，你确定你要\n跟过来？\n&甘宁\n你能离得开我？没有我，你应该什么都\n做不成吧。\n&陆抗\n很抱歉，因为我的独断独行，把你给\n拖下水了。\n&甘宁\n孙綝这家伙为了一己之私，宁愿把三万\n大吴军队丢下都要回军。\n&甘宁\n他制造的怨恨早晚会把他吞掉，一年内就\n可以预见他的败亡。\n&陆抗\n就因为这样，所以我才想要多拯救点\n这些被围困的将士，就算只救到一个\n也好。\n&甘宁\n不只这样吧…诸葛靓的那封信似乎也对你\n影响不小，是牵动你对陆逊的感情吧。\n&陆抗\n十年前，我看著爹被小人围攻，却没有\n办法帮他一点忙，我是眼睁睁看著他被\n人害死。\n&陆抗\n现在我却有这个能力去帮忙拯救别人的\n父亲，如果我不做，就是再度犯下当时\n的错误。\n&甘宁\n你想太多了，陆逊的情况不是你可以挽回\n的，同样援救诸葛诞也不是你能力所及。\n&陆抗\n为什么你说话总是这么不留情？\n&甘宁\n不过我不讨厌像你这样的人，所以我\n才会帮你。\n&甘宁\n更何况，如果我的预感没有错，那个疯子\n恐怕会有惊人的举动。\n&陆抗\n疯子？你是说文俶？\n&甘宁\n除了他，还有谁呢？这几年来，他对我\n挑衅了无数次，你知道这代表什么？\n&陆抗\n他是个连自己人都不放过的疯子？\n&甘宁\n对，这种人没有什么原则，千万别把\n一般人的价值观套到他身上。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[11]},{"op":"change_scene","args":[2,65535,65535,24,65535]},{"op":"actor_appear","args":[128,48,49,2,0]},{"op":"actor_appear","args":[18,48,59,0,3]},{"op":"actor_appear","args":[19,48,65,0,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["赵家受辱"]},{"op":"place_name","args":["寿春防卫军军营"]},{"op":"dialog","args":["&赵统\n弟弟快离远一点，这家伙强得跟怪物\n一样。\n&文鸯\n就这种水准？你的动作慢到苍蝇都可以\n停在身上了。\n&文鸯\n这才是真正的速度！"]},{"op":"delay","args":[5]},{"op":"actor_select","args":[0,128,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"dialog","args":["&赵广\n不见了？"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[128,48,54,2,0]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"dialog","args":["&赵统\n什么？\n&文鸯\n太慢了！"]},{"op":"delay","args":[5]},{"op":"play_music","args":[34,1]},{"op":"delay","args":[5]},{"op":"play_music","args":[35,1]},{"op":"delay","args":[5]},{"op":"dialog","args":["&赵统\n啊！"]},{"op":"actor_action","args":[18,10]},{"op":"play_music","args":[38,1]},{"op":"delay","args":[5]},{"op":"dialog","args":["&文鸯\n你真的是赵云的儿子？我曾经听说赵云有\n万夫不当之勇，结果你却被我一击打倒。\n&赵统\n可恶…完全不能动弹…\n&赵广\n你突然攻击我大哥，让我大哥来不及防备\n，难道就公道？\n&文鸯\n不服气的话，你也攻过来呀。\n&赵统\n不要…这家伙合我们兄弟之力都不是\n对手。\n&文鸯\n不应该是这样的…不应该是这样的…\n&文鸯\n我真恨我晚生了五十年，不能和那些强悍\n的武将一较高下。\n&文鸯\n到现在我只碰过一个让我觉得惊艳的武将\n，只是在我在东吴这段期间，她一直拒绝\n和我交手。\n&文鸯\n本来以为你这个赵云之子可以让我惊喜\n一下，没想到终究是让我失望。\n&赵广\n你别得意，我们赵家的武艺，绝对不只\n如此而已。\n&文鸯\n你比起你兄长更是可悲，你兄长虽然不敌\n，但还表现出武将的气魄，但是你呢？你\n只是躲在旁边发抖而已。"]},{"op":"actor_face","args":[128,0,0]},{"op":"dialog","args":["&赵统\n（连他什么时候挥剑的都不知道，这家伙\n也太可怕了。）\n&赵统\n（可恶，为什么我会这么不堪一击，难道\n我的实力真的只有这样？）\n&赵统\n（人家关家和张家后人都有表现，而我\n赵统却害父亲被人嘲笑…）\n&赵广\n（面对真正的高手，我居然连挺身而对的\n勇气都没有，我真是丢父亲的脸。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[31]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[127,40,53,1,0]},{"op":"actor_appear","args":[179,49,57,3,0]},{"op":"actor_appear","args":[180,49,51,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["吴将的志气"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"dialog","args":["&文钦\n防务大概都安置妥当了，我想面对敌军\n攻击，应该也可以挡得住。\n&唐咨\n有件事情我想问问，镇北大将军您真的\n愿意和诸葛诞合作？\n&文钦\n我比谁都讨厌诸葛诞，当年如不是诸葛诞\n在后面阻挠，我和仲恭恐怕早就可以打败\n司马师了。\n&唐咨\n那么您有什么理由为他卖命？\n&文钦\n为了大义，我战死于此也在所不惜。\n&唐咨\n大义值多少钱？您要知道，城中有三万\n大吴军队被困在这里，要是城破，大家\n都没有生还机会。\n&唐咨\n您是出身名门，可以有谯县文家的骄傲。\n但我不是，我唐咨是从烂泥堆中打滚出来\n的，我只求存活就好。\n&文钦\n我记得你当年慷慨激昂，在利城起兵反抗\n文帝，怎么现在没有当年的勇气？\n&唐咨\n那时我一个人漂流到大吴，靠著军功爬到\n高位，享受了过去从没有享受过的荣华富\n贵。\n&唐咨\n我终于想通了，什么壮烈牺牲都是鬼扯，\n只有保全自己性命才是最重要的事情。\n&文钦\n你说的我也明白，仲恭也对我这样说过。\n&文钦\n但是，我已经厌烦这样的生活了，我不想\n再回去东吴过著寄人篱下的日子，我想要\n在这里光荣地结束自己的生命。\n&唐咨\n那么您的儿子们呢？他们年轻的生命就该\n这样消失？\n&文钦\n这也是无可奈何的事情，他们也都愿意\n为这样的大义而死，不是吗？\n&唐咨\n真是自私呀！\n&于诠\n我已经多久没有听过这样慷慨激昂的发言\n，为什么我大吴已经没有这样的武将？\n&于诠\n这几年来，我每天看著应该是自己人的\n武将大臣在那互相砍杀，却无一人愿意\n和外敌交战牺牲。\n&于诠\n我神往过去长沙桓王平定江东的威武，\n也赞叹周郎以寡击众的气魄，曾几何时\n，我大吴居然变成充斥著偷生者的国度。"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[180,6]},{"op":"dialog","args":["&于诠\n镇北大将军，我的性命就交给您了，\n就算死，也要死得像是个武将。\n&唐咨\n真是一窝笨蛋，好吧，我也陪你们到最后\n一刻了。\n&文钦\n实在是不胜感激。\n&唐咨\n倒是…全家那群人跑哪去了？为什么这个\n重要时刻会看不到全家人？"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[25]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[95,29,54,1,0]},{"op":"actor_appear","args":[1,48,41,2,0]},{"op":"actor_appear","args":[18,56,41,2,0]},{"op":"actor_appear","args":[19,71,41,2,0]},{"op":"actor_appear","args":[128,78,41,2,0]},{"op":"actor_appear","args":[127,46,68,0,0]},{"op":"actor_appear","args":[179,56,68,0,0]},{"op":"actor_appear","args":[196,71,68,0,0]},{"op":"actor_appear","args":[180,78,68,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["摆荡的忠义"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"dialog","args":["&诸葛诞\n从司马昭军队的动向来看，似乎准备要对\n寿春发动总攻击了。\n&诸葛诞\n我们就用寿春坚固的城墙，来让司马昭\n大军都葬身于此。"]},{"op":"actor_face","args":[127,2,3]},{"op":"dialog","args":["&文钦\n都是你的馊主意，什么淮河一定暴涨，\n你看现在一滴雨都没下。\n&文钦\n结果我们眼睁睁看著敌人把寿春围得跟\n铁桶一样，全都是你害的。"]},{"op":"actor_action","args":[95,0]},{"op":"dialog","args":["&诸葛诞\n怪我了？！我怎么知道今年寿春会突然\n遭逢大旱？"]},{"op":"actor_action","args":[95,0]},{"op":"actor_action","args":[127,0]},{"op":"dialog","args":["&文钦\n算了，面对敌人的攻击，我军也该派人\n在城外游击，守住城外的据点。\n&诸葛诞\n你认为该派谁去守？这可是非常危险的\n任务。\n&文钦\n就让我的两个儿子去，相信你也见过当时\n在乐嘉之战之中阿鸯的表现了吧。\n&诸葛诞\n（不对劲，难道文家兄弟是想先在城外\n投降司马昭，然后再和文钦在城内来个\n里应外合？）\n&文钦\n到了这个时候，你还在猜忌吗？！你认为\n我文钦会投降司马昭？司马师的性命记在\n我们父子名下，我们怎么可能投降他？\n&诸葛诞\n不，我没有这个意思。"]},{"op":"actor_face","args":[180,0,3]},{"op":"actor_face","args":[179,0,3]},{"op":"dialog","args":["&于诠\n我可以保证文将军的忠诚，我们大吴军队\n也都决定要在这里和寿春共存亡了！\n&唐咨\n我或许是数姓家奴，但这次，我想好好\n打场漂亮的仗！"]},{"op":"actor_face","args":[128,6,3]},{"op":"dialog","args":["&文鸯\n就让我顺手摘下小昭昭的脑袋吧，我等\n这一刻已经很久了。\n&诸葛诞\n（诸葛果为什么不说一句话，还有这对\n赵家兄弟，如果他们开口的话，我可以\n随时派他们接替文家父子。）\n&文鸯\n赵家兄弟是绝对无法担当这个重任的，\n昨天我已经试过他们的实力了。\n&赵统\n………\n&赵广\n………\n&诸葛诞\n好吧，寿春小城的守备工作就劳烦你了。\n&诸葛诞\n成功失败，就在这一刻，我们要守住寿春\n，让司马家知道正义是站在哪一方！\n&文钦\n（正义是你这种人可以说的？）"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[127,0,0]},{"op":"actor_face","args":[180,0,0]},{"op":"actor_face","args":[179,0,0]},{"op":"actor_face","args":[128,0,2]},{"op":"play_sound","args":[21]},{"op":"battle_select_units","args":[1,3,65535,65535,18,19,1,0,65535,65535,65535,65535]},{"op":"battle_select_units","args":[1,3,65535,65535,65535,65535,65535,65535,65535,65535,65535,65535]},{"op":"battle_select_units","args":[1,3,65535,65535,65535,65535,65535,65535,65535,65535,65535,65535]},{"op":"endif","args":[]},{"op":"dialog","args":["&诸葛诞\n出发，打倒司马昭！"]},{"op":"battle_select_units","args":[0,0,65535,65535,65535,65535,65535,65535,65535,65535,65535,65535]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[255]},{"op":"endif","args":[]},{"op":"dialog","args":["&诸葛诞\n我想问你，现在的我…是否稍微接近族兄\n一些了？\n&诸葛果\n功绩上或许略有不及，但是精神上已经\n相当接近了。\n&诸葛诞\n如果是你说的，应该是真的吧。\n&诸葛诞\n我很崇拜族兄，虽然是敌对阵营，但是\n他的《出师表》和《正议》都看得我感\n动不已，这样的人，实在是我的榜样。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&赵统\n（我不甘心，虽说我武艺和天份都不及父\n亲，但也不应该会面对文鸯到毫无招架之\n力。）"]},{"op":"endif","args":[]},{"op":"dialog","args":["&赵广\n（为什么我会变得这么胆怯，过去我在\n战场上，不管面对实力多强的对手，不\n都应该挺身面对吗？）\n&赵广\n（这样下去，我怎么能面对当年命丧我手\n的魏家兄弟呢？）"]},{"op":"endif","args":[]},{"op":"dialog","args":["&诸葛诞\n希望我们这次可以携手合作，打倒司马昭\n，回复大魏的秩序。\n&文钦\n我虽然很讨厌你，但是现在也只有和你\n合作，才有帮昭伯和仲恭报仇的可能。\n&诸葛诞\n（你这家伙眼中就永远没有我？曹爽优柔\n寡断，咎由自取。毌丘俭抱著不切实际的\n空想送死，我哪点比不上那群笨蛋？）\n&文钦\n（诸葛诞，你还是不明白你和那些人的差\n距？他们都是可以为理想而死的英雄，而\n你却永远在理想与现实的中间摆荡。）"]},{"op":"endif","args":[]},{"op":"dialog","args":["&文鸯\n上次司马师麾下没有让人感到印象深刻的\n将领，这次司马昭会不会让我失望？\n&文鸯\n司马昭，你看见你自己的死兆星了吗？"]},{"op":"endif","args":[]},{"op":"dialog","args":["&唐咨\n这场仗，我是决定要打到底了！就像当年\n挺身对抗曹贼的暴政一样。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&于诠\n这场战斗，就算拚上我的性命，也要让大\n吴军队的名声，在这场战斗中彰显！"]},{"op":"endif","args":[]},{"op":"dialog","args":["&全怿\n（全辉和全仪这两个混蛋居然给我投奔敌\n营，现在我回到大吴，恐怕也很难说不会\n被追究。）\n&全怿\n（更危险的是，本来以为孙綝不会对我们\n江东士族动刀，但是自从朱异被杀之后，\n我也很难相信他不动我们钱塘全家。）\n&全怿\n（现在我到底该怎么办呢？）"]},{"op":"endif","args":[]},{"op":"enter_battle","args":[]}]},"battles":[{"src":"S_25"}]});
})();
